INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A1', 1, 'Будинок моєї сім''ї', '["Наша сім''я живе в будинку біля парку. У будинку живуть мама, тато, мій брат і я. Мама працює в школі, тато працює в магазині, а брат ходить у дитячий садок. Уранці всі поспішають, але ввечері ми знову разом.","На першому поверсі є кухня і вітальня. На кухні мама часто готує суп, а у вітальні ми дивимося телевізор. Там стоїть диван, стіл і велика шафа. У шафі лежать книжки, фото і настільні ігри.","На другому поверсі є наші спальні. Моя кімната невелика, але в ній є ліжко, стіл і книжки. У дворі тато ставить лавку, і влітку ми часто сидимо там разом. Брат грається з м''ячем, а я дивлюся на дерева біля парку. Увечері мама приносить чай, і ми говоримо про день. Наш дім простий, але дуже рідний."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A1', 2, 'Книги та іграшки', '["Мене звати Софійка, і я дуже люблю книги та іграшки. У моїй кімнаті є полиця з казками і велика коробка з іграшками. Я часто сиджу біля полиці після школи. Спочатку я вибираю книжку, а потім відкриваю коробку.","Щовечора я читаю коротку книжку з малюнками. Моя улюблена книжка розповідає про дівчинку і ліс. Я читаю її багато разів, бо добре знаю героїв. Іноді мама слухає мене і допомагає читати нові слова.","У коробці лежать кубики, лялька і маленька машина. З кубиків я будую будинок, а лялька живе в цьому будинку. Коли мама читає зі мною, я повторюю нові слова. Потім я граюся і вигадую маленьку історію. Іноді я записую ім''я героя на папері і малюю поруч маленький будинок."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A1', 3, 'Мій будинок', '["Я живу в невеликому будинку біля саду. У будинку є чотири кімнати: кухня, спальня, вітальня і ванна кімната. Біля дверей стоїть полиця для ключів і взуття. На кухні стоїть стіл і чотири стільці. Уранці ми снідаємо там разом і говоримо про день.","У вітальні стоїть диван, низький столик і годинник на стіні. На дивані лежить теплий плед. У моїй спальні є ліжко, шафа і лампа біля ліжка. На столі лежать книжка і телефон. Я люблю свій будинок, бо він теплий і спокійний. Увечері я читаю у вітальні, а мама п''є чай на кухні. На вихідних я прибираю кімнату і ставлю книжки на свою полицю."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A1', 4, 'Мій день', '["Уранці я прокидаюся і відкриваю вікно. Потім я йду у ванну кімнату, мию руки та обличчя. На кухні я їм хліб із сиром і п''ю воду.","Після сніданку я йду до школи. У школі я читаю, пишу і слухаю вчителя. Після школи я повертаюся додому, обідаю і роблю вправи. Потім я складаю книжки на стіл.","Увечері я гуляю біля дому. Потім я дивлюся мультфільм, а мама готує вечерю. Я вечеряю з родиною і рано лягаю спати."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A1', 5, 'Мій звичайний день', '["Я прокидаюся о сьомій годині і не поспішаю вставати. Потім я йду у ванну кімнату, мию обличчя і чищу зуби. На кухні я їм кашу і п''ю теплий чай. Після сніданку я перевіряю сумку і беру ключі.","До школи я йду пішки. На уроках я слухаю вчителя, читаю текст і пишу в зошиті. На перерві я їм яблуко і говорю з другом. Ми часто говоримо про футбол або домашнє завдання.","Після школи я повертаюся додому, обідаю і трохи відпочиваю. Потім я роблю домашнє завдання, гуляю з другом і вечеряю з родиною. Перед сном я кладу книжки в сумку і ставлю будильник. Такий порядок допомагає мені почуватися спокійно. Якщо я все готую ввечері, ранок проходить легко. Я знаю, де лежать мої речі."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A1', 6, 'Мої домашні тварини', '["У мене вдома живуть кіт і два собаки. Кота звати Мурчик. Він сірий, тихий і любить сидіти біля вікна. Уранці Мурчик дивиться на двір і чекає сніданок. Першого собаку звати Бім, а другого Рекс.","Бім великий і добрий, а Рекс малий і швидкий. Щодня я годую тварин. Коту я даю їжу в миску, а собакам даю воду і сухий корм. Увечері всі лежать біля мене, і вдома стає спокійно. Мама теж часто гладить Мурчика. Після вечері я усміхаюся."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A1', 7, 'Мої канікули', '["У мене починаються канікули, і я не йду до школи. Уранці я сплю довше, а потім повільно снідаю. Мама готує млинці, а я п''ю чай і дивлюся у вікно.","Удень я гуляю з друзями в парку. Там є гойдалка, лавка і велика доріжка. Ми граємо в м''яч, а потім купуємо морозиво.","Увечері я читаю книжку або допомагаю вдома. Я мию тарілки після обіду і складаю іграшки в коробку. У серпні ми їдемо до Одеси, тому я дуже чекаю цю поїздку. Я хочу бачити море і збирати мушлі на пляжі. На канікулах день довгий, і я маю більше часу для гри, читання та прогулянок."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A1', 8, 'Моя м''яка іграшка', '["У мене є улюблена м''яка іграшка. Це коричневий ведмедик, якого звати Тедді. У нього круглі вуха, чорні очі і дуже м''які лапи. Він невеликий, тому я легко беру його з собою.","Тедді сидить на моєму ліжку майже весь день. Увечері я беру його в руки, читаю книжку і відпочиваю. Коли мені сумно, ведмедик завжди лежить поруч.","Мама подарувала мені Тедді на день народження. Іграшка вже не нова, але вона дуже дорога для мене. Я часто ставлю Тедді на подушку і кажу йому добраніч."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A1', 9, 'Моя чудова родина', '["У мене є чудова родина. Моя мама добра і спокійна, вона готує сніданок і часто читає книжки. Мій тато веселий, він працює в офісі і любить музику.","У мене є сестра Ліза. Вона ходить до школи і любить малювати квіти. Ще у нас є дідусь, який часто розповідає цікаві історії. У неділю він приходить до нас на обід.","Увечері ми сидимо разом на кухні. Ми п''ємо чай, говоримо про день і сміємося. Ліза показує малюнок, тато слухає, а мама усміхається. Я дуже люблю свою родину. Коли мені потрібна допомога, родина завжди поруч. Тому вдома мені легко і тепло."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A1', 10, 'На пошті', '["Сьогодні я йду на пошту, бо маю лист для тітки. Пошта стоїть біля магазину. Я кладу лист у сумку і беру адресу.","На пошті працює привітна жінка. Вона питає адресу, і я читаю її з паперу. Потім жінка бере лист, дає марку, і я плачу гроші.","Після цього я беру квитанцію і кажу: Дякую. Біля пошти стоїть лавка, тому я сідаю на хвилину. Увечері я кажу мамі, що лист уже їде до тітки."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A1', 11, 'Нова машина для сім''ї', '["Моя сім''я хоче купити нову машину, бо стара машина часто стоїть у гаражі. Тато дивиться машини в телефоні, а мама думає про колір і місце для сумок. Я хочу зручне заднє сидіння. Нам потрібна машина для роботи, школи і поїздок до бабусі.","У суботу ми йдемо в автосалон. Там стоїть біла машина, вона чиста, велика і дуже гарна. Тато сідає за кермо, мама відкриває багажник, а я сідаю назад. Продавець показує нам двері, фари і нові колеса.","Ми купуємо цю машину і їдемо додому повільно. Тато веде машину обережно, мама усміхається, а я дивлюся у вікно. Тепер ми можемо зручно їздити до бабусі."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A1', 12, 'Новий однокласник', '["Сьогодні в наш клас приходить новий хлопець. Його звати Данило, і він сідає біля мене. Я кажу: Привіт, мене звати Оля. Данило усміхається і відповідає: Привіт, дуже приємно. Учитель просить нас показати Данилу розклад.","На перерві я питаю Данила, де він живе. Він каже, що живе біля парку. Потім ми говоримо про хобі. Данило любить футбол і шахи, а я люблю футбол і книжки. Після уроків ми разом ідемо додому. Завтра ми знову сидимо поруч у класі. Він показує мені новий пенал, а я показую йому шкільний двір. Мені легко говорити з ним українською."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A1', 13, 'Поїздка з мамою', '["Сьогодні я їду з мамою на машині до бабусі. Мама сидить за кермом, а я сиджу поруч і тримаю квіти. У машині грає тиха музика, тому дорога здається приємною. Мама питає мене про школу, і я розповідаю про уроки.","Ми їдемо через місто і бачимо магазин, аптеку та школу. Потім машина їде біля річки, і я дивлюся на воду. Мама питає, чи я взяв подарунок, і я показую квіти. Я також беру маленький пиріг у коробці.","Через двадцять хвилин ми приїжджаємо. Бабуся стоїть біля воріт і радіє нам. Я даю їй квіти, мама ставить сумку на стілець, і ми сідаємо за стіл."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A1', 14, 'Розклад занять студента', '["Мене звати Максим, і я навчаюся в коледжі в Києві. У понеділок я встаю о сьомій годині, бо перше заняття починається о дев''ятій. Я беру зошит, ручку, книжку і йду до школи. Біля входу я зустрічаю друга Андрія. Ми разом ідемо в клас і дивимося розклад на дверях.","Після занять я заходжу в бібліотеку. Там тихо, тому я читаю текст і роблю домашнє завдання. У середу в мене українська мова і математика, а в четвер історія. У п''ятницю ми пишемо короткий тест. Увечері я готую сумку, перевіряю олівці і заряджаю телефон. Потім я трохи відпочиваю вдома."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 1, 'Мій день', '["Будильник дзвонить о сьомій, і я розплющую очі. У кухні вже пахне чаєм. Мама гукає з коридору: «Олю, вставай!» Я вмиваюся, застеляю ліжко і йду на кухню. На столі вже стоїть тепла каша з медом. Я снідаю, беру рюкзак і виходжу з дому.","О восьмій годині я вже стою біля школи. Дорога недовга, тому я ніколи не поспішаю. У школі в мене чотири уроки, перерва і обід. Найбільше я люблю сидіти біля вікна, бо звідти видно старий каштан у дворі. На перерві ми з подругою їмо яблука. Після уроків ще трохи розмовляємо біля воріт.","Додому я приходжу о третій. Спочатку відпочиваю, а потім роблю домашнє завдання. Увечері я читаю книжку про далекі мандри. За вікном темніє, і в кімнаті стає тихо. Я закриваю книжку і всміхаюся: день був простий і добрий."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 2, 'Моя сім''я', '["Удома мене кличуть Тарасиком, а в школі — Тарасом. Нас у сім''ї четверо. Мама, тато, молодша сестра Марійка і я. Ми живемо в маленькому будинку біля саду. Влітку там цвітуть старі яблуні, і вікна нашої кухні дивляться прямо на них.","Мама працює в школі, а тато — в майстерні. Марійка ще ходить у дитячий садок. Вона любить малювати і щовечора показує мені нові картинки. Я кажу, що вони гарні, і вона одразу біжить по нові олівці. Увечері ми вечеряємо разом і розповідаємо, як минув день. Тато завжди питає першим.","У суботу ми прибираємо, готуємо обід і нікуди не поспішаємо. Тато вмикає радіо, а Марійка сідає малювати просто на підлозі. Мама розливає гарячий чай у великі чашки. Я люблю свою сім''ю саме за такі дні. У такі хвилини ніхто не дивиться на годинник."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 3, 'Мій будинок', '["Я живу з батьками у квартирі на третьому поверсі. Наш будинок стоїть біля невеликого магазину і автобусної зупинки. Квартира не дуже велика, але світла, тепла і зручна. У ній є кухня, вітальня і дві кімнати. З вікна видно тихий двір, лавку і кілька старих дерев.","На кухні ми снідаємо і говоримо про плани на день. У вітальні стоїть диван, круглий столик і полиця з книжками. Увечері там тихо, тому мама часто читає, а тато відпочиває після роботи. Найбільше в цій квартирі мені подобається моя кімната. Я роблю уроки біля вікна, а потім слухаю музику або читаю.","Торік ми з татом пофарбували тут стіни, і я сам вибрав колір. Тут тепло і тихо. Я сідаю біля вікна і довго не хочу нікуди йти."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 4, 'У школі', '["Я навчаюся в п''ятому класі. У нас аж дві Марини, тому мене всі кличуть Маринкою. Школа стоїть недалеко від дому, тому вранці можу йти зовсім повільно. У класі в мене є подруги, з якими я сиджу на перервах.","Мій улюблений предмет — математика. Мені подобається рахувати, розв''язувати задачі і знаходити правильну відповідь. Коли задача важка, я не здаюся одразу, а читаю умову ще раз. Учителька спокійно допомагає нам і ніколи не сварить. Сьогодні в нас також є урок малювання. Вона роздає нам аркуші і кольорові олівці.","Ми малюємо осінній парк, жовте листя і лавку біля дерева. Я довго вибираю потрібний олівець. На перерві ми обговорюємо малюнки і сміємося з маленьких помилок. Свою роботу я кладу в папку дуже обережно. Додому я йду з гарним настроєм."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 5, 'Мій друг', '["Мого найкращого друга звати Іван. Ми живемо на одній вулиці і ходимо до однієї школи. Зранку він чекає мене біля свого двору, навіть коли йде дощ. Потім ми разом ідемо на уроки і говоримо про футбол або домашнє завдання.","Іван веселий і добрий. На перервах ми часто стоїмо біля вікна або розмовляємо з однокласниками. Після школи ми майже щодня граємо у футбол на майданчику. Іван добре бігає і часто забиває голи, але ніколи не хвалиться. Я стою на воротах, бо бігаю гірше.","Коли мені важко, Іван допомагає. Він може пояснити задачу або дати мені потрібний зошит. Торік я довго хворів, і він щодня приносив мені домашнє завдання. Я теж стараюся бути таким другом для нього. У неділю ми телефонуємо одне одному і плануємо гру на понеділок."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 6, 'У магазині', '["Мама: Добрий день. Мені, будь ласка, молоко, хліб і кілограм яблук. Продавчиня: Добрий день. Молоко у холодильнику біля входу, а свіжий хліб щойно привезли. Мама: Тоді візьму дві пляшки молока і одну хлібину. Продавчиня: Хліб іще теплий. Беріть, поки не охолов. Мама: Дуже добре. А які яблука сьогодні найсолодші? Продавчиня: Ось ці червоні, з нового врожаю. Вони солодкі й зовсім недорогі. Мама: Тоді покладіть кілограм, будь ласка. Продавчиня: Готово. Щось іще потрібно? Мама: А пакет у вас є? Продавчиня: Так, звичайно. Мама: Ні, дякую, більше нічого. Де у вас каса? Продавчиня: Каса праворуч, біля вікна. Я вас проведу. Мама: Дякую. Я плачу карткою. Продавчиня: Ось ваш чек. Гарного вечора! Мама складає молоко, хліб і яблука в торбу, дякує ще раз і виходить. На вулиці вже пахне дощем."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 7, 'Мій улюблений спорт', '["У вівторок і четвер я після школи йду не додому, а в басейн. Мене звати Соня, і плавання — мій улюблений спорт. Два рази на тиждень — і цього мені досить. Беру сумку, купальник і великий рушник. Басейн зовсім недалеко від нашої школи.","У басейні нас зустрічає тренерка. Вона показує, як рухати руками і спокійно дихати у воді. Спочатку я роблю вправи біля бортика, а потім пливу повільно. Я не поспішаю, бо хочу зробити все правильно. Після заняття руки важкі, але я знаю, що стаю сильнішою.","Удома я розповідаю мамі, що сьогодні пливла краще. Мама усміхається і наливає мені гарячий чай. Я вже думаю про наступний вівторок. У сумці сохне купальник, а рушник висить на батареї біля вікна. Наступного тижня я знову піду до басейну після уроків."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 8, 'Погода сьогодні', '["Сьогодні ранок хмарний і холодний. Я дивлюся у вікно й бачу сіре небо над будинками. У дворі немає сонця, і мокрі дерева стоять зовсім нерухомо. На вулиці дме вітер, тому я надягаю теплу куртку і шарф. Мама каже з кухні: «Дмитре, шапку не забудь.» Дощу поки немає, але погода все одно неприємна. До школи я йду швидко і весь час тримаю руки в кишенях.","Після уроків я нарешті повертаюся додому. У під''їзді вже тепліше, і мені стає легше. Вдома я знімаю куртку, вішаю шарф біля дверей і п''ю гарячий чай. У кімнаті затишно, а на столі світить маленька настільна лампа. Я чую, як за вікном тихо шумить холодний вітер. Мама приносить плед і вмикає радіо на кухні. Сідаю робити домашнє завдання і зовсім не хочу нікуди виходити."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 9, 'Що я їм на сніданок', '["Щоранку на кухні пахне кашею з медом. Це мій сніданок, і він не змінюється роками. Мама варить кашу на маленькій плиті, поки я вмиваюся і збираю рюкзак. Вона тепла і трохи солодка. Друзі звуть мене Настею і сміються, що я щоранку їм те саме.","Іноді я п''ю какао, особливо коли надворі холодно. У чашці воно пахне шоколадом, і ранок стає приємнішим. Я не їм багато різних страв, бо вранці часу мало. Але кілька ложок каші з медом я їм завжди. Мама називає це найкращим початком дня.","Після сніданку в мене з''являється енергія на цілий ранок. Я краще слухаю вчительку і не думаю про їжу до перерви. Потім беру куртку, кажу мамі до побачення і виходжу з дому. Тепер я готова до нового дня."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 10, 'Мої домашні тварини', '["Кота я назвав Рудиком, бо він рудий. Мене звати Колін, і Рудик живе в нас уже три роки. Він м''який і дуже спокійний. Уранці Рудик сидить біля миски і чекає на їжу. Коли я насипаю корм, він тихо муркоче і дивиться на мене зеленими очима.","Удень Рудик часто спить на дивані у вітальні. Він любить тепле місце біля великої подушки. Якщо хтось сідає поруч, кіт відкриває одне око, але не встає. Мама сміється і каже, що Рудик справжній господар дивана.","Щовечора я граюся з Рудиком після уроків. Я кидаю йому маленький м''ячик, а він біжить за ним по кімнаті. Потім він лягає біля моїх ніг, коли я читаю. Я гладжу його по спині і чую, як він муркоче. У такі хвилини я завжди усміхаюся."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 11, 'Маршрутка або автобус', '["Моя зупинка — біля невеликого магазину на розі. Мене звати Андрій, і щодня я їжджу на роботу цим автобусом. З дому я виходжу раніше, бо не люблю поспішати. Автобуса треба чекати хвилин десять. Я стою біля дороги і дивлюся, як повільно прокидається вулиця.","Коли автобус приїжджає, я заходжу через передні двері. Квиток коштує дев''ять гривень, тому дрібні гроші я готую заздалегідь. У салоні часто багато людей, але їхати мені недовго. Я тримаюся за поручень і дивлюся у вікно. За склом пропливають будинки, мокрі дерева і ранкові вітрини.","Біля роботи я виходжу на третій зупинці від дому. Потім іду пішки повз аптеку і кав''ярню, де вранці завжди пахне кавою. Дорога проста, тому я ніколи не плутаюся. На роботу я приходжу вчасно і встигаю випити чаю."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 12, 'У лікаря', '["Аня: Добрий день, лікарю. Я погано почуваюся. У мене болить горло, і я швидко втомлююся на уроках. Лікар: Добрий день, Аню. Сідай, будь ласка. Скажи, коли це почалося? Аня: Позавчора ввечері, після довгої прогулянки. Лікар: Це схоже на звичайну застуду, але тобі треба добре відпочити. Аня: А я можу завтра піти до школи? У нас важливий урок. Лікар: Краще залишись удома. Пий теплий чай, більше спи і не виходь на холод. Нехай мама допоможе тобі з уроками. Аня: А ліки потрібні? Лікар: Поки ні, головне — тепло і сон. Аня: Добре, я послухаю вас. Лікар: Через три дні тобі має стати значно краще. Удома Аня п''є теплий чай, лежить у ліжку і читає просту книжку. Через три дні вона вже сама збирає рюкзак до школи."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 13, 'Мій вільний час', '["Після уроків я найбільше люблю ту годину, коли нікуди не треба поспішати. Мене звати Богдан. Спочатку я вечеряю і відпочиваю хвилин десять біля вікна. Потім вмикаю музику. Слухаю спокійні пісні, бо вони допомагають забути про втому.","Ще я часто малюю. У моєму зошиті є дерева, будинки, машини і люди на зупинці. Малюю я не дуже добре, але мені це подобається. На столі завжди лежать кольорові олівці і стара точилка. Іноді ввечері я дивлюся мультфільми з молодшим братом. Малюнки я складаю в стару папку.","Найбільше я люблю вихідні. У суботу зовсім не треба поспішати після школи. Можу довше малювати, слухати музику або просто сидіти біля вікна. У неділю ми всі разом п''ємо чай на кухні. Брат просить намалювати йому машину, і я малюю."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 14, 'Дні тижня', '["У понеділок після школи я йду на тренування. Мене звати Катя, і мій тиждень має простий порядок. Там ми бігаємо, робимо вправи і вчимося працювати разом. Після цього я спокійно вечеряю вдома. Уроки роблю вже пізно ввечері.","У середу в мене знову тренування. Я вже знаю, що треба покласти в рюкзак: футболку, воду і рушник. Після заняття я трохи втомлена, але мені подобається рухатися.","У п''ятницю я зустрічаюся з друзями біля школи. Ми гуляємо, говоримо про уроки і сміємося з маленьких історій. Це приємний кінець навчального тижня.","У суботу я прибираю свою кімнату. Складаю книжки, витираю стіл і відкриваю вікно. Потім кімната стає світлою і чистою. Увечері я сідаю і думаю, що встигла за тиждень. У неділю я вже знаю, яким буде понеділок."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 15, 'День пам''яті жертв Чорнобиля', '["На дошці написані дата і одне слово: Чорнобиль. Сьогодні двадцять шосте квітня, день пам''яті. Учителька говорить дітям про аварію на Чорнобильській станції. Вона пояснює простими словами, що це був важкий день для багатьох людей. Діти слухають уважно і майже не рухаються.","На столі стоять маленькі свічки. Учителька роздає їх дітям і показує, як тримати вогник рівно і безпечно. Діти обережно запалюють свічки одну від одної. У класі стає так тихо, що чути годинник. Потім усі мовчать одну хвилину. Ніхто не говорить, бо кожен розуміє, що це особливий момент.","Після уроку діти виходять у коридор і довго розмовляють пошепки. Один хлопчик каже, що вдома обов''язково розповість про урок бабусі. Учителька ставить свічки на підвіконня, і вони горять до кінця дня. Тепер діти знають, чому цей день тихий."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 16, 'Новий рік', '["Мене звати Тимко. Раніше, до 2022 року, Новий рік у нашій родині був дуже гучним. Тридцять першого грудня ми готували святковий стіл, а першого січня прокидалися пізніше. На столі були салат олів''є, мандарини, бутерброди і шампанське для дорослих. Ми не спали до півночі, вітали одне одного і дивилися у вікно на феєрверки. У дворі сміялися сусіди, а діти раділи кольоровим вогням.","Після початку повномасштабної війни наш Новий рік змінився. У місті стало менше гучних вечорів. Ми не запускаємо феєрверки, бо це може лякати людей і заважати спокою. Іноді ввечері буває повітряна тривога, тому ми слухаємо новини і тримаємо потрібні речі поруч. Молодша сестра питає, чому надворі так тихо. Батьки кажуть, що головне тепер — безпека і підтримка одне одного. Ми говоримо тихіше і частіше дякуємо за спокійний вечір.","Та Новий рік не зник із нашого дому. Ми однаково накриваємо стіл, чистимо мандарини і говоримо теплі слова. Мама ставить олів''є в гарну миску, а тато тихо відкриває шампанське для дорослих. Опівночі ми обіймаємося і бажаємо миру. Бабуся телефонує, а потім ми робимо сімейне фото біля маленької ялинки. Я дивлюся на родину і розумію: свято стало тихішим, але воно теж важливе. Я щасливий, що ми разом."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 17, 'День Соборності України', '["У класі на дошці висить велика карта України. Сьогодні двадцять друге січня, День Соборності. Біля карти лежать сині й жовті стрічки. Учителька показує карту дітям і каже, що цього дня країна згадує важливу подію.","Вона пояснює, що в 1919 році дві частини України об''єдналися. Для дітей це складна історія, тому вчителька говорить просто. Вона каже, що соборність означає єдність. Це коли люди з різних міст і сіл відчувають себе разом. Діти ставлять кілька запитань і слухають відповіді.","Потім діти беруться за руки і роблять у класі маленький ланцюг єдності. Стає весело і трохи гамірно. Вони називають міста: Київ, Львів, Харків, Одесу. Після цього діти прикріплюють стрічки до карти. Учителька киває і каже, що в Україні живе багато різних людей, але країна одна. Діти розуміють просту ідею: Україна — це один спільний дім."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 18, 'Різдво Христове', '["У нашій родині Різдво святкують двадцять п''ятого грудня. Бабуся пам''ятає, що раніше багато родин робили це сьомого січня. Мене звати Оленка, і я знаю цей день з дитинства. Це великий і теплий день в Україні. Зранку вдома тихо, але всі вже мають багато справ. Мама готує страви, тато ставить свічку на стіл, а я допомагаю складати серветки.","Увечері сім''я збирається за столом. Бабуся рахує: пісних страв має бути дванадцять, тобто без м''яса. На столі кутя, вареники і смажена риба. Свічка горить посеред столу до самого кінця вечері. Ми їмо повільно і говоримо спокійно.","Після вечері до нас приходять діти колядувати. Вони співають короткі колядки, а ми даємо їм цукерки і трохи грошей. Мені подобається слухати ці тонкі голоси біля дверей. Коли вони йдуть, у сінях ще довго пахне морозом."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 19, 'День Героїв Небесної Сотні', '["Двадцятого лютого Настя йде з мамою до невеликого меморіалу в місті. Біля нього стоять квіти і свічки. Мама говорить тихо, бо це день пам''яті Героїв Небесної Сотні. Настя тримає маму за руку і дивиться на маленькі вогники. Вона бачить, що люди підходять повільно і не шумлять.","Настя питає маму: чому цих людей називають героями? Мама пояснює просто. Вона каже, що на Майдані були люди, які хотіли чесного і вільного життя для країни. Вони зробили важкий вибір, тому люди пам''ятають їх.","Настя кладе маленьку квітку біля свічок. Вона ще мала, але добре бачить повагу на обличчях дорослих. Поруч стоїть старша жінка і тихо поправляє стрічку на букеті. Мама бере Настю за руку і каже, що пам''ять допомагає людям бути добрішими і сильнішими. Настя ще раз озирається на свічки, перш ніж піти."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 20, 'Міжнародний жіночий день', '["Восьмого березня я прокидаюся раніше, ніж зазвичай. Мене звати Сашко, і сьогодні я хочу привітати маму. Тато тихо допомагає мені знайти вазу і чистий конверт. У домі ще темно, і ми з татом говоримо пошепки.","Квіти я купив учора і сховав їх у себе в кімнаті. Це невеликий букет, але я вибирав його дуже довго. Листівку я підписав пізно ввечері, коли всі вже спали. Усередині написано: «Мамо, ти найкраща». Я довго старався, щоб букви вийшли рівні й гарні.","Коли мама заходить на кухню, я даю їй квіти і підписану листівку. Вона читає мої слова, усміхається і міцно обіймає мене. Мені трохи соромно, але дуже приємно. Тато теж усміхається і ставить букет у вазу біля вікна. Мама каже, що це найкращий подарунок для неї."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 21, 'Вишиванка — мій одяг', '["Сьогодні в школі свято, тому я вдягаю свою вишиванку. Мене звати Даринка, і ця сорочка в мене вже два роки. Вона біла, легка і дуже приємна на дотик. На рукавах є червоний орнамент. Я обережно застібаю ґудзики, розчісую волосся і дивлюся в дзеркало.","Мама заходить до кімнати і усміхається. Вона каже, що моя вишиванка дуже красива. Я трохи червонію, бо мені приємно це чути. Потім мама поправляє комір і просить не забути рюкзак. У коридорі вже чекає молодший брат. У школі багато дітей теж приходять у вишиванках.","У класі світло і святково. Ми робимо фото біля дошки і довго вибираємо, хто де стане. Подруга питає, чи зручна моя сорочка, і я кажу, що дуже. Увечері я вішаю вишиванку на плічка, щоб вона не пом''ялася до наступного свята."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 22, 'Борщ — улюблена страва', '["Щосуботи моя бабуся готує великий борщ. Зранку в хаті вже тепло і смачно пахне овочами. Я сиджу біля столу і дивлюся, як бабуся дістає овочі. Вона бере буряк, картоплю, капусту і квасолю. Від нього борщ стає яскраво-червоним.","Бабуся працює повільно. Вона каже, що добрий борщ не любить поспіху. Я допомагаю подати тарілки, ложки і хліб. Мені цікаво, як прості овочі стають такою смачною стравою. Різати я ще не вмію, тому просто дивлюся і питаю.","Коли борщ готовий, уся сім''я сідає за стіл. Ми їмо його зі сметаною і свіжим чорним хлібом. Тато просить добавки, а мама сміється і накладає йому ще одну повну миску. Бабуся радіє, коли всім смачно. Ми довго говоримо за столом і нікуди не йдемо. Ніхто не встає з-за столу першим."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 23, 'Великдень', '["На Великдень наша сім''я встає ще затемна. Надворі тихо, але вдома вже світиться кухня. Мене звати Оля, і цей ранок я чекаю цілий рік. Мама перевіряє кошик, а тато бере чистий рушник. У кошику лежать паска, крашанки і ковбаса. Я несу маленьку свічку і йду поруч із мамою.","Ми йдемо до церкви повільно, бо ранок прохолодний. Біля входу стоять інші родини з кошиками. Після служби люди усміхаються, обіймаються і кажуть: «Христос Воскрес!» Я теж повторюю ці слова і міцніше тримаю маму за теплу руку.","Коли ми повертаємося додому, на столі вже чекають тарілки. Я вибираю найяскравішу крашанку. Родина сідає разом, і в кімнаті стає тепло від розмов. Бабуся розрізає паску, а я допомагаю подати чай. Ми стукаємося крашанками, і моя витримує найдовше з усіх."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 24, 'Вареники на обід', '["У неділю я приходжу до бабусі на обід. На кухні пахне свіжим тістом, а на столі лежить білий рушник. Удома мене звуть Марійкою, а бабуся — Марічкою. Сьогодні вона робить вареники з картоплею. Я дуже люблю цю страву і відразу біжу мити руки.","Бабуся показує мені, як обережно тримати вареник у руках. Вона довіряє мені тільки просту роботу, зате вчить бути уважною. Я кладу готові вареники на тарілку і стежу, щоб вони не торкалися. Тісто на пальцях швидко висихає і стає зовсім білим. Бабуся сміється і показує, як його змити.","Коли обід готовий, бабуся подає вареники зі смаженою цибулею. Вони м''які і дуже смачні. Ми їмо разом і довго говоримо про школу і сусідів. Вона каже, що наступного разу навчить мене ще краще."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 25, 'Хліб та сіль', '["Бабуся Олена чекає гостей разом зі своєю маленькою онукою Софійкою. На столі лежить вишитий рушник. На ньому — круглий хліб і маленька сільниця. У кімнаті чисто, і біля дверей уже стоять готові капці. Софійка дивиться на стіл і питає, чому хліб лежить так красиво.","Бабуся пояснює, що в Україні гостей часто зустрічають хлібом і сіллю. Вона каже, що це давній знак поваги і гостинності. Коли людина вперше приходить у дім, господарі показують, що раді її бачити. Софійка слухає уважно і киває.","Скоро гості заходять до хати. Софійка допомагає бабусі подати гостям хліб і сіль. Вона бачить, як люди усміхаються і тихо дякують. Потім усі сідають за стіл і починають довгу розмову. Тепер дівчинка знає, навіщо хліб цілий ранок чекав гостей на рушнику."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 26, 'Моя вулиця', '["Машини на нашій вулиці їдуть повільно, наче нікуди не поспішають. Мене звати Леся, і вулиця в нас довга і тиха. Уздовж дороги стоять невеликі будинки з тихими садами. Уранці я бачу, як сусіди йдуть на роботу, а діти несуть рюкзаки до школи. Потім усе знову стихає.","Біля нашого будинку є маленький парк. У ньому ростуть кілька старих дерев і стоять дві лавки. Поруч є дитячий майданчик із гойдалками і гіркою. Після уроків я часто проходжу повз нього і бачу знайомих дітей.","Щовечора після вечері діти граються на майданчику. Хтось катається на гойдалці, хтось бігає або малює крейдою на доріжці. Дорослі сидять на лавках і тихо розмовляють. Увечері тут чути сміх і далекий гавкіт собак. Я знаю тут кожне дерево і кожну лавку біля дому."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 27, 'Перший дзвоник — День знань', '["Першого вересня біля школи дуже людно. Це День знань, і новий навчальний рік починається урочисто. Учні приходять у чистому одязі, тримають квіти для вчителів і шукають свої класи. Батьки роблять фото і тихо бажають дітям успіху.","Найбільше хвилюються першокласники. Вони вперше заходять до школи з великими рюкзаками. Деякі діти тримають батьків за руку, а інші сміливо дивляться на двері. Біля них стоять старші учні і допомагають знайти клас.","Учителька вітає всіх і просить дітей стати ближче. Потім старша учениця піднімає маленький дзвоник над головою. Він дзвенить голосно і коротко, і всі плескають у долоні.","Після цього діти заходять до класів. У коридорі пахне квітами і новими зошитами. Першокласники трохи мовчать, але скоро усміхаються. Учителька каже, що кожен день принесе нові знання. Двері класів зачиняються одні за одними, і в коридорі стає тихо."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 28, 'Покупки на ринку', '["У неділю тато йде на ринок. Він бере велику торбу і список покупок. Ринок уже відкритий, і між довгими рядами ходить багато людей. На столах лежать овочі, фрукти і зелень. Мама просила вибрати все найкраще. Тато хоче купити продукти для недільного обіду.","Біля одного столу він бачить свіжі помідори і зелені огірки. Продавець вітається і показує йому найкращі овочі. Тато бере помідори, огірки і пучок кропу з петрушкою. Він уважно перевіряє все, бо вдома цього вже не виправиш. Продавець усміхається і дає йому маленьку знижку.","Тато дякує, платить і кладе покупки в торбу. Він не затримується довго, бо вдома чекає родина. Дорогою він думає про салат і теплий суп, який сьогодні зварить мама. Скоро тато повертається додому зі свіжими продуктами і гарним настроєм."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 29, 'Я допомагаю вдома', '["Щовечора після вечері я мию посуд. Мене звати Артем, і це моя робота вже давно. Спочатку ставлю тарілки біля раковини, потім мию їх теплою водою. Витираю все рушником і складаю посуд у шафу. Молодша сестра іноді подає мені чисті чашки.","У суботу я прибираю кімнати пилососом. Мені не завжди хочеться це робити, але я знаю, що так вдома стає чистіше. Починаю зі своєї кімнати, а потім переходжу до коридору. Мама поруч готує обід. Пилосос гуде так голосно, що ми не чуємо одне одного.","Коли я закінчую, мама дякує мені. Вона каже, що моя допомога справді важлива. Потім ми разом обідаємо у чистій світлій кухні. Сестра ставить на стіл вазу з польовими квітами. Я сідаю останнім і бачу, що все на своєму місці."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 30, 'День матері', '["День матері приходить у другу неділю травня. Мене звати Коля, і подарунок я почав готувати ще в суботу. Купувати щось дороге я не хотів. Увечері я взяв білий аркуш, олівці і сів за письмовий стіл. У кімнаті було зовсім тихо, тому думалося легко.","На листівці я намалював квіти, сонце і наш маленький будинок. Слова написав усередині, великими рівними літерами: «Мамо, я тебе люблю». Тато порадив підписати дату, і я зробив це дуже уважно. Потім я сховав листівку під подушку до ранку.","У неділю зранку я мовчки дав листівку мамі. Вона прочитала, усміхнулася і раптом заплакала від радості. Потім мама обійняла мене і повісила листівку на холодильник біля сімейного фото. Вона довго дивилася на неї і нічого не казала. Листівка висить там і досі."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 31, 'День вишиванки', '["У третій четвер травня в школі святкують День вишиванки. Мене звати Остап, і цей день я чекаю щороку. Зранку я вдягаю білу сорочку з синім орнаментом. Мама каже, що її колись вишила моя бабуся.","Коли я приходжу до школи, бачу багато кольорів. Уся школа сьогодні у вишиванках. Учні стоять у коридорах, вітаються і показують одне одному свої сорочки. Навіть учителі приходять у вишитих сорочках.","На великій перерві наш клас робить фото біля вікна. Потім ми говоримо про родинні орнаменти. Один хлопчик каже, що на його сорочці є чорні й червоні нитки. Дівчинка показує стару вишиванку своєї мами.","Після уроків я акуратно складаю сорочку в рюкзак. Мені подобається, що цього дня всі одягнені по-різному, але почуваються разом. Дорогою додому я думаю про бабусю, яка шила цю сорочку. Удома я вішаю її поруч із маминою."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 32, 'У кафе', '["Рома і Юля зустрічаються після уроків біля маленького кафе. Надворі прохолодно і сіро, тому вони швидко заходять усередину. Усередині тепло, пахне кавою і свіжою випічкою. Друзі сідають біля вікна, де видно тиху вулицю. Вони кладуть рюкзаки під стіл і знімають шапки.","Офіціантка підходить до їхнього столика. Рома замовляє каву, бо хоче трохи зігрітися. Юлі більше хочеться яблучного соку і маленького печива. Вони не дивляться довго на меню, бо прийшли просто поговорити після довгого дня. Офіціантка приносить усе досить швидко.","Рома розповідає про смішний випадок на уроці, а Юля сміється. Потім вони довго говорять про домашнє завдання і плани на вихідні. Час минає швидко. За вікном темніє, і на вулиці одна за одною вмикаються ліхтарі. Виходять вони останніми, уже майже перед закриттям."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 33, 'Моя улюблена їжа', '["Найбільше з усього на світі я люблю піцу. Мене звати Петрик, і в їжі я не дуже вибагливий. Мені подобається тонке тісто, гарячий сир і теплий соус. Коли тато приносить піцу додому, я відразу біжу на кухню і допомагаю ставити тарілки. Я завжди вибираю шматок, де найбільше сиру і соусу.","Моя бабуся сміється і каже, що вареники набагато смачніші. Вона робить їх з картоплею або з домашнім сиром. Я не сперечаюся з бабусею, бо її страва справді дуже добра. Тісто м''яке і тепле.","Тепер я думаю, що обидві страви чудові кожна по-своєму. Піцу я люблю їсти з друзями, а вареники — тільки з бабусею. Коли ми сидимо разом за столом, їжа здається значно смачнішою. Бабуся розповідає смішні історії, а я слухаю і зовсім забуваю жувати."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 34, 'Зима в Україні', '["Узимку в Україні часто лежить сніг. Ранок буває дуже холодним, але вулиці виглядають світлими і тихими. Дерева стоять білі. На дахах будинків теж лежить сніг, і місто здається зовсім новим і тихим. Діти після школи виходять у двір і ліплять сніговиків. У парках вони катаються на санчатах з невеликих гірок. Іноді батьки теж виходять надвір і допомагають дітям будувати гірку.","Дорослі вдягають теплі куртки, шапки і товсті рукавиці. Увечері вікна світяться, а вдома пахне чаєм і мандаринами. Найкраще зимове свято для багатьох людей — Новий рік. Родини збираються разом, вітають одне одного і згадують минулий рік. Діти чекають подарунків і довго не лягають спати. Надворі мороз, а в кімнатах тепло і світло від ялинкових гірлянд. Зима холодна, але вона може бути дуже радісною."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 35, 'Писанка — мистецтво розпису яєць', '["Перед Великоднем я приходжу до бабусі і бачу на столі яйця та фарби. Мене звати Дарина, і сьогодні я вчуся писати писанку. Біля вікна лежать серветки і тонкий олівець. Бабуся каже, що писанка — це не просто кольорове яйце. Це маленький предмет мистецтва. Я сідаю поруч і дуже хочу спробувати.","Бабуся показує мені прості знаки. Сонце означає світло, квітка нагадує про весну, а хвиля схожа на воду. Більше знаків вона поки не показує. Я обережно малюю тонкі лінії і стараюся не поспішати. Коли рука тремтить, бабуся спокійно підтримує мене.","Моя перша писанка виходить не зовсім рівною, але я радію. На ній є маленьке сонце, квітка і синя хвиля. Бабуся каже, що головне — робити все з увагою. Вона ставить її на серветку біля вікна, щоб фарба висохла. Проти світла синя хвиля здається майже прозорою."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 36, 'Числа і гроші', '["Олег іде до маленького магазину біля дому. У кишені він має гроші, а в руці тримає короткий список. Мама просила купити сік і шоколад. Олег уважно дивиться на полицю, бо хоче вибрати правильно і не помилитися. Магазин невеликий, і продавчиня знає його в обличчя.","Пляшка яблучного соку коштує двадцять гривень. Невелика шоколадка коштує п''ятнадцять гривень. Олег не поспішає і кладе обидві речі в кошик. Ще раз дивиться на цінники, щоб бути впевненим. Біля каси він вітається з продавчинею і ставить покупки на стіл.","Вона називає суму, і Олег платить готівкою. Вона дає йому решту і чек. Олег кладе все в пакет, але не йде одразу. Спочатку він перевіряє сік, шоколад і решту. Усе правильно. Потім Олег дякує, усміхається і виходить із магазину."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 37, 'Моя мама', '["Моя мама працює медсестрою. Вона прокидається дуже рано, коли в квартирі ще тихо. Мене звати Настя, і я рідко бачу її вранці. Мама швидко п''є чай, бере сумку і перевіряє, чи має ключі. Я іноді прокидаюся і бачу її вже біля дверей.","Увечері мама повертається додому втомлена. Вона знімає пальто, миє руки і сідає на кухні. Я майже нічого не питаю про роботу, бо знаю, що їй потрібен спокій. Замість цього я ставлю їй чашку теплого чаю.","Потім мама завжди обіймає мене. Навіть коли вона дуже втомлена, її обійми теплі і добрі. Ми трохи говоримо про мій день, уроки і подруг. Перед сном вона бажає мені доброї ночі і гасить світло. Уранці все почнеться спочатку, і я знаю, що чашка чаю чекатиме на неї знову."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 38, 'Пісня на уроці', '["Сьогодні в нас урок музики. Учителька заходить до класу і відкриває старе піаніно. Мене звати Олена, і музику я люблю найбільше. На дошці вона пише тему сьогоднішнього заняття. Вона каже, що сьогодні ми будемо вчити стару народну пісню. Її назва — «Ой, у лузі червона калина».","Спочатку ми слухаємо мелодію. Учителька грає на піаніно повільно, щоб усі добре зрозуміли ритм. Потім вона просить нас сидіти рівно і дихати спокійно. Деякі слова складні, але ми повторюємо їх разом без поспіху. Мені допомагає подруга за партою.","Після кількох спроб клас співає краще. Я чую голоси друзів навколо і стараюся не збиватися. Учителька усміхається і знову починає грати спочатку. На останніх хвилинах уже ніхто не соромиться. Наприкінці ми співаємо всі разом, і піаніно вже ледве чути за голосами."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 39, 'Тварини на фермі', '["Улітку я часто їжджу до дідуся на ферму. Мене звати Петрик, і тут я вже не гість. Там є корови, кури і свині. Я не боюся тварин, але завжди слухаю дідуся. Він каже, що на фермі треба бути спокійним і уважним.","Уранці всіх тварин треба годувати. Дідусь несе корм для свиней, а я допомагаю йому тримати відро. Потім ми даємо зерно курям. Корови стоять біля хліва і чекають на свою їжу. Я бачу, що кожна тварина має свій час.","Після роботи ми з дідусем сідаємо біля будинку і п''ємо воду. Він дякує мені за допомогу і каже, що я вже добре знаю ранкові справи. Руки пахнуть сіном, і я весь мокрий від роботи. Завтра вранці все почнеться знову, і я вже знаю кожен крок."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 40, 'Хто де живе', '["Я живу в місті, де багато будинків, магазинів і автобусів. Мене звати Софія, і я знаю тут кожен двір. Мені подобається, що школа близько, а після уроків можна піти до бібліотеки. У місті завжди є що робити.","Моя бабуся живе в селі, і я відвідую її влітку. Там тихі ранки, широке небо і мало машин. Біля села є річка, куди ми ходимо гуляти після обіду. У бабусі також є великий сад з яблунями і квітами. Уранці там чути тільки птахів і далекий трактор.","Я не порівнюю місто і село. Вони просто різні. У місті я вчуся і бачу друзів, а в селі відпочиваю. Увечері ми з бабусею сидимо в саду і п''ємо чай. Яблуня над нами вже зовсім стара і скрипить від вітру."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 41, 'День Конституції України', '["Учителька кладе на стіл невелику книжку в синій обкладинці. Сьогодні двадцять восьме червня, День Конституції. Вона каже, що Конституція — це головний закон нашої країни. У класі тихо, бо тема звучить серйозно і незвично. Але вчителька говорить дуже просто і спокійно.","Вона пояснює, що громадяни мають права. Наприклад, право вчитися і вільно говорити свою думку. Але в кожного є ще й обов''язки. Треба поважати інших, берегти країну і не заважати людям поруч себе. Один учень раптом питає, чи це схоже на правила класу.","Потім учні самі наводять прості приклади зі школи. Клас має бути безпечним. І кожен повинен не заважати іншим. Учителька погоджується і каже, що це дуже хороший приклад. Наприкінці уроку діти розуміють головну ідею: права і обов''язки завжди йдуть разом."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 42, 'Дорога до школи', '["Я щодня ходжу до школи пішки. Мене звати Іринка, і дорога займає приблизно десять хвилин. Після сніданку я беру рюкзак і закриваю двері великим ключем. Мама махає мені з вікна. Я махаю у відповідь і повертаю за ріг біля аптеки.","Спочатку я проходжу повз невеликий тихий парк. Там ростуть старі дерева, а біля доріжки стоїть зелена дерев''яна лавка. Восени під ними завжди повно жовтого сухого листя. Потім я йду повз магазин, де вранці вже купують свіжий теплий хліб. Я вітаюся із сусідкою, якщо бачу її біля входу.","Далі дорога веде прямо до школи. Я ніколи не поспішаю, бо добре знаю свій час. Біля воріт уже стоять кілька моїх однокласників. Ми вітаємося і разом заходимо всередину. У роздягальні я спокійно вішаю куртку і чую перший дзвінок."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 43, 'Мій день народження', '["Сьогодні мій день народження, і мені виповнюється десять років. Мене звати Данило, і цього ранку я став на рік старшим. Зранку мама будить мене усмішкою. На кухні вже пахне тортом. Мама пече його сама і ставить зверху маленькі свічки. Я рахую їх і радію.","Після обіду до мене приходять друзі. Вони приносять прості подарунки і кілька яскравих кульок. Один друг дарує книжку, а інший приносить кольорові олівці. Ми не робимо великої вечірки, але нам весело. Ми граємо в настільну гру, говоримо і сміємося.","Потім мама виносить торт зі свічками. Друзі співають коротке привітання, а я загадую бажання. Ми їмо по невеликому шматку торта. Я дякую всім за подарунки і добрі слова. Увечері кульки ще висять біля вікна, і я довго не хочу лягати спати."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 44, 'Ранок у сім''ї', '["У нашій сім''ї ранок починається рівно о сьомій годині. Дзвонить будильник, і всі повільно прокидаються. Мене звати Марійка, і я встаю першою. Я застеляю ліжко, брат шукає шкарпетки, а тато вже йде на кухню. У коридорі вже чути швидкі кроки.","Тато готує каву для себе і для мами. На кухні тепло, і вікно вже запітніло від пари. Мама варить кашу для всієї сім''ї. Вона ставить на стіл миски, ложки і жовті яблука. Я наливаю воду в склянки.","О восьмій годині всі вже готові виходити з дому. Тато бере сумку, мама перевіряє ключі, а ми з братом беремо рюкзаки. Перед самими дверима ми швидко бажаємо одне одному гарного дня. Двері зачиняються, і в домі стає зовсім тихо. До вечора наша квартира чекатиме порожня."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 45, 'Річка Дніпро', '["Дніпро — найбільша річка України. Він протікає через багато великих міст і малих сіл. Біля води люди гуляють, відпочивають і довго дивляться на течію. У Києві Дніпро широкий, тому з мостів добре видно його береги. Вранці вода може бути спокійною, а ввечері на ній блищить світло. На березі часто сидять цілі родини з термосами і бутербродами. Для багатьох ця річка є частиною щоденного життя.","Улітку біля Дніпра завжди багатолюдно. Діти і дорослі купаються там, де це безпечно. Хтось сидить на березі з вудкою і терпляче ловить рибу. Інші просто приходять подихати свіжим повітрям або посидіти на теплій траві. Поруч можна побачити рибальські човни і чайок. Дніпро важливий для країни, бо він дає воду, красу і місце для відпочинку. Багато людей люблять цю річку."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 46, 'День Незалежності України', '["Мене звати Микола. До 2022 року День Незалежності України був для нашої родини дуже гучним святом. Двадцять четвертого серпня ми з батьками йшли в центр міста. Там проходив парад, грала музика, люди несли прапори і вітали одне одного. Після параду ми слухали концерт на площі і купували морозиво. Увечері родина дивилася феєрверки, і небо було яскравим.","Після російського повномасштабного вторгнення свято змінилося. У місті вже немає такого шуму і великих феєрверків. Батьки кажуть, що тепер головне — безпека і повага до людей, які переживають важкі часи. Ми можемо дивитися короткий концерт онлайн або слухати українські пісні вдома. Іноді сусіди тихо вітають одне одного у дворі і бажають спокійного дня. На балконі тато все одно вішає синьо-жовтий прапор. Я допомагаю йому тримати стрічку, щоб він висів рівно.","Тепер День Незалежності став тихішим, але не менш важливим. Ми накриваємо простий стіл, говоримо про Україну і згадуємо, що свобода дуже важлива. Мама каже, що любити країну можна і в звичайний день. Я дивлюся на прапор і думаю про майбутнє. У цей день я особливо слухаю слова батьків. Потім ми телефонуємо бабусі і разом вітаємо її зі святом. Прапор на балконі видно з вулиці до самого вечора."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 47, 'Відпочинок в Одесі та на Чорному морі', '["Мене звати Назар Петренко. Улітку наша сім''я їде до Одеси на два тижні. Ми довго чекаємо цієї поїздки, бо всі любимо море. Наш готель недалеко від пляжу, тому зранку ми швидко беремо рушники і йдемо до води. Іти туди лише кілька хвилин.","Ми з сестрою багато плаваємо в Чорному морі. Вода тепла, а хвилі іноді легенько штовхають нас до берега. Після купання ми їмо морозиво і сидимо під парасолькою. Потім збираємо мушлі, але беремо тільки кілька найкрасивіших. Мама просить нас не відходити далеко.","Тато каже, що Чорне море найкраще, бо біля нього легко відпочивати. Мама усміхається і робить фото нашої сім''ї. Увечері ми гуляємо біля готелю і слухаємо шум води. Я згадую цей звук навіть перед сном і довго дивлюся у вікно. Мені подобається Одеса, і я дуже хочу приїхати сюди знову."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 48, 'День захисників і захисниць', '["Першого жовтня в Україні вшановують захисників і захисниць. Мене звати Вікторія, і для мене це дуже особливий день. У школі вчителька говорить про людей, які бережуть країну. Я слухаю дуже уважно, бо мій тато служить в армії. Він далеко від дому, і я часто думаю про нього.","Після уроків я сідаю за стіл і роблю листівку. На ній малюю синє небо, жовте поле і маленьке серце. Усередині пишу: «Тату, ми тебе чекаємо». Я стараюся писати рівно, бо хочу, щоб тато легко прочитав мої слова. Молодший брат малює поруч маленький синій прапор.","Мама допомагає з конвертом. Вона каже, що такі слова підтримують тата краще за все. Увечері я дивлюся на татове фото і трохи сумую. Конверт лежить на столі і чекає на завтрашню пошту."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 49, 'День Гідності та Свободи', '["Учителька вимикає світло і вмикає коротке відео про Майдан. Сьогодні двадцять перше листопада, День Гідності та Свободи. Учні сідають тихо. На екрані вони бачать площу, прапори, людей у теплих куртках і багато світла. У класі ніхто не розмовляє.","Після відео вчителька говорить простими словами. Вона каже, що люди вийшли на Майдан, бо хотіли свободи і поваги. Складних пояснень вона не дає і сперечатися не просить. Потім вона питає, що означає це слово в їхньому власному житті. Учні думають і відповідають по черзі.","Один хлопчик каже, що свобода — це можливість говорити правду. Дівчинка додає, що за неї треба вміти відповідати. Учителька усміхається і пише ці слова на дошці. Потім клас кілька хвилин мовчить і про щось думає. Наприкінці уроку діти розуміють це слово краще, ніж на початку."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 50, 'День пам''яті жертв Голодомору', '["У четверту суботу листопада Україна згадує жертв Голодомору. Учителька розповідає про це тихо і просто. Вона пояснює, що в 1932-1933 роках багато людей загинули від штучного голоду. На дошці написані роки і слово пам''ять. Діти слухають уважно, бо розуміють, що це день пам''яті.","Свічки запалюють і ставлять на вікна рівно о сьомій вечора. Маленьке світло видно з вулиці, і в будинках стає тихіше. Одна родина ставить свічку на підвіконня біля хліба і кількох колосків. Далі по вулиці горить ще кілька таких вогників. Батьки кажуть дітям, що так люди показують: ми пам''ятаємо.","Ніхто не говорить голосно. Родина стоїть біля вікна кілька хвилин і дивиться на теплий вогник. Діти не знають усіх важких деталей, але розуміють головне: пам''ять потрібна людям. Бабуся тихо тримає руку онуки. Свічка у вікні стає тихим знаком поваги і пам''яті."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 51, 'Традиція Івана Купала', '["Увечері я прийшов з братом до річки, бо було свято Івана Купала. Біля води вже збиралася молодь з нашого села. Хлопці ставили лавки, а дівчата несли польові квіти. Поруч діти сиділи з батьками і чекали пісень. На березі було тепло, світло і дуже спокійно.","Моя подруга Марічка плела вінок з ромашок, м''яти і синіх квітів. Поруч інші дівчата теж вибирали квіти для своїх вінків. Потім вони тихо клали вінки на воду. Кожна дівчина мала своє бажання. Люди казали, що вінок, який пливе далеко, приносить щастя в коханні.","Я стояв на березі і дивився на річку. Вода повільно несла квіти, а небо ставало рожевим. Ми слухали пісні, сміялися і пили чай з термоса. Я довго пам''ятав тиху воду. Вінок Марічки поплив далеко і зник за поворотом."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 52, 'Переїзд у нове місто', '["Мене звати Оксана, і моя сім''я Коваленко переїхала з Полтави до Львова. У машині лежали коробки, сумки, іграшки і наші книжки. У мене в рюкзаку лежав старий класний альбом. Я сиділа біля вікна та думала про наш двір. Мій молодший брат теж трохи сумував за друзями і школою.","Коли ми приїхали, Львів здавався великим і незнайомим. Я бачила вузькі вулиці, старі будинки і високі двері. Тато казав, що тут особлива архітектура. Мама показала нам затишні кав''ярні біля площі. У новій квартирі ще пахло фарбою і деревом.","Першого вечора ми гуляли недалеко від дому. У дворі сусідка привіталася з нами. Я написала подрузі повідомлення і пообіцяла приїхати в гості. Потім побачила маленьку книгарню, парк і дітей біля фонтану. Мені стало спокійніше. Я зрозуміла, що новий початок може бути добрим. Львів повільно став мені подобатися."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 53, 'Як готують пампушки', '["У суботу я прокинувся рано, бо в кухні вже пахло тістом. Бабуся Галина готувала пампушки до борщу. Вона усміхнулася і сказала, що поспішати тут не можна. Вона дозволила мені подати чистий білий рушник. Я сів за стіл, узяв чашку гарячого чаю і почав уважно дивитися.","Бабуся замішувала дріжджове тісто. Я ще не вмію так, але бачив, яке воно м''яке. Потім вона робила маленькі круглі кульки і рівно ставила їх на деко. Уранці теплий запах наповнив увесь дім і коридор.","Коли пампушки були готові, бабуся змастила їх часниковим маслом. Я допоміг поставити тарілки на стіл і покликав тата з двору. На плиті вже стояв борщ. Мені дуже хотілося скуштувати їх одразу. До обіду треба було почекати ще зовсім трохи. Перша пампушка обпекла мені пальці."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 54, 'Прогулянка Львовом', '["Туристи приїхали до Львова вранці і відразу пішли на площу Ринок. Вони хотіли побачити центр міста без поспіху. На площі стояли старі будинки з гарними вікнами. Туристи робили фото, дивилися вгору і слухали коротку розповідь гіда. Одна жінка фотографувала синій балкон над кафе.","Потім вони зайшли на вузьку вулицю біля площі. Там були маленькі крамниці, книгарні і кав''ярні. У вікнах лежали листівки, чашки, шоколад і сувеніри. Біля одного будинку грали вуличні музиканти. Діти слухали їх біля дверей. Їхня музика звучала легко, і люди зупинялися на кілька хвилин.","Львів здавався туристам середньовічною казкою. Тут кожна вулиця була іншою, але гуляти містом було легко. Настрій був святковий і спокійний. Увечері вони купили листівки для друзів і ще раз подивилися на площу. Туристи сказали, що хочуть повернутися до Львова знову."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 55, 'Перший заробіток', '["Минулого літа я вперше заробив свої гроші. Мене звати Данило, і мені тоді було дванадцять років. Наша сусідка тітка Лариса попросила мене допомогти в саду. Я приходив до неї після сніданку і працював одну годину. Робота була проста, але потрібна, тому я не запізнювався.","Я поливав грядки, збирав сухе листя і носив воду до молодих дерев. Іноді було жарко, тому я робив коротку перерву в тіні. Сусідка дякувала мені і казала, що сад виглядає краще. Вона навіть показала мені свої нові квіти. Наприкінці тижня вона дала мені гроші.","Я купив собі цікаву книжку і морозиво біля магазину. Решту поклав у коробку. Тоді я зрозумів, що гроші приходять через працю і час. Коробка стоїть там і досі, і я нічого з неї не брав."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 56, 'Великдень: традиції і значення', '["Великдень є важливим святом в Україні, але його дата щороку інша. Щоб знайти точний день, люди дивляться церковний календар. Зазвичай це неділя після весняного повного місяця. Це правило не завжди легко порахувати самому. Так родина знає, коли пекти паску, фарбувати яйця і готувати кошик.","Сім''ї святкують Великдень по-різному. Одні йдуть до церкви вночі, коли ще темно і тихо. Інші приходять уранці з дітьми, бо так зручніше. Біля храму люди вітаються спокійно і радісно. У багатьох людей є великодній кошик. У ньому лежить паска, яйця, сир, ковбаса і маленька свічка.","Наприклад, одна сім''я з Києва пече паску вдома, а сусіди купують її в пекарні. Хтось фарбує яйця в суботу, а хтось робить це раніше. Після служби люди вітають одне одного і сідають за стіл. У домі стає світло і святково. Молодші слухають старших, але додають свої звички. Так старі й нові традиції живуть разом."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 57, 'Українська вишивка', '["Українська вишивка живе в багатьох родинах. Бабусі передають сорочки, рушники і знання своїм дітям та онукам. Дівчина може отримати вишиту сорочку від мами. Хлопець може берегти рушник, який зробила його бабуся. Так пам''ять родини переходить від покоління до покоління.","У різних регіонах є свої орнаменти і кольори. Десь люди люблять червоний і чорний, а десь синій, зелений або білий. На сорочках можна побачити квіти, листя і прості геометричні знаки. Кожен узор щось означає. Найчастіше він пов''язаний з домом і родиною.","Вишиванка є не тільки красивим одягом. Для багатьох людей це знак того, хто вони і звідки. Це також пам''ять і гордість. Її носять на свята, у школі або на важливі зустрічі. Коли люди вдягають вишиту сорочку, вони часто згадують свою сім''ю. Тому вишивку носять бережно і з повагою."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 58, 'Мандрівка Карпатами', '["Мене звати Христина, і моя сім''я Шевченко провела тиждень у Карпатах. Ми жили в маленькому будинку біля лісу. Навколо росли ягоди і високі трави. Щоранку я відкривала вікно і бачила зелені гори. Повітря було свіже, тому всі швидко прокидалися і хотіли йти надвір.","Удень ми ходили простими стежками в горах. Тато показував нам дерева, а мама фотографувала краєвиди. Ми не поспішали і часто відпочивали біля великих каменів. Ми дихали свіжим повітрям і багато мовчали. У рюкзаку були бутерброди, вода і яблука. Після обіду ми з братом довго плавали в чистій холодній річці біля села.","Увечері ми сиділи на лавці й пили теплий чай. Мій брат сказав, що це найкращі канікули. Інші діти теж погодилися з ним. Мама усміхалася. Я думала так само. Удома в рюкзаку ще довго пахло димом і хвоєю."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 59, 'Як я навчився готувати', '["Улітку мама почала вчити мене готувати прості страви. Мене звати Артем, і раніше я не підходив до плити. Спочатку я тільки мив овочі і подавав тарілки. Потім мама сказала, що я вже можу зробити щось сам. Я записував поради у маленький зошит. Мені було цікаво і трохи страшно.","Першою стравою були варені яйця. Я дивився на годинник і слухав мамині поради. Після цього я навчився варити гречку в маленькій каструлі. Вона не завжди була ідеальна, але сім''я їла її з усмішкою і хвалила мене.","Пізніше ми разом смажили котлети. Мама стояла поруч і показувала, коли їх треба перевернути. Тепер я можу приготувати простий обід для всієї родини: гречку, салат і котлети. Це вже схоже на справжню допомогу вдома. Я ще питаю поради і прибираю після себе, але вже почуваюся більш самостійним."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 60, 'Моя бабуся і її рецепти', '["Мою бабусю звати Параска. Вона знає багато рецептів, але не любить довго про них говорити. Мене вдома кличуть Катрусею. Ми з братом приїжджаємо до неї на вихідних. На кухню ми заходимо найпершими. Бабуся радіє і одразу ставить на плиту чайник.","Найкраще бабуся готує куліш і тонкі млинці. Одне вона ставить у велику миску, друге складає на тарілку. У хаті смачно пахне їжею і свіжим гарячим чаєм. Я люблю дивитися, як вона все це готує. Бабуся додає, що добра страва потребує любові й терпіння.","Ми допомагаємо накривати великий стіл. Я ставлю ложки, а брат приносить свіжий хліб. Після обіду бабуся обов''язково питає, чи все було смачно. Ми киваємо і просимо ще млинців із медом. Вона знову йде до плити, хоча ми вже давно наїлися і сміємося."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 61, 'Традиційний одяг різних регіонів', '["У старій скрині святкова сорочка лежить зверху. У кожному регіоні України такі сорочки виглядають по-своєму. Колись таку сорочку вдягали на весілля і великі родинні свята. Решту року вона чекала в темряві, складена рівно вчетверо. Колір і візерунок одразу показували, звідки людина родом. А ще вони говорили про смак родини і про працю майстрині.","На Полтавщині вишивають червоними і чорними нитками. Узор виходить рівний, спокійний, майже без зайвих деталей. У гуцульських селах усе інакше. Там люблять яскраві кольори, теплі кептарі, широкі пояси і багато прикрас. Це пасує до гірських доріг, гучної музики і швидких танців. Одяг тримає в собі те, чим живе край.","Сьогодні такі сорочки не носять щодня, але їх дістають на свята і вистави. У музеї вони стоять за склом, і діти довго порівнюють кольори. Хтось обов''язково впізнає узор свого краю."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 62, 'Козацька історія', '["Посеред Дніпра лежить довгий зелений острів Хортиця. Саме там колись була головна громада запорізьких козаків. Козаки були сміливими воїнами, а головне — вільними людьми. Вони самі обирали собі отамана і разом вирішували важливі справи. Ніхто не наказував їм, як жити. Слово і честь важили для них більше за багатство.","Козаки захищали свою землю і людей, які жили поруч. Коли приходила біда, вони не стояли осторонь. Життя на Січі було суворе й просте. Вони разом працювали, разом їли і слухали старших. Той, хто хотів бути вільним, мусив уміти жити поруч з іншими людьми. У цьому й була сила громади.","Сьогодні про козаків нагадують пісні, танці й старі легенди. На святах діти танцюють гопак, а в музеях слухають розповіді про Хортицю. Майже в кожній родині знають хоча б одну козацьку пісню. Козаків не забули."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 63, 'Калина — символ України', '["Повз кущ біля нашої школи я проходив сто разів. Він просто ріс собі коло паркану, і я на нього не дивився. А сьогодні вчителька принесла в клас гілку з червоними ягодами. Вона сказала, що червона калина — символ України. Я впізнав той кущ одразу. Мені стало трохи соромно, що я його не помічав.","Потім ми говорили, де ще можна зустріти калину. Вона є в піснях, у вишивці і в старих віршах. Бабуся справді часто співає про червону калину. Ще вчителька дала нам спробувати ягоду. Ягода виявилася гіркою, і половина класу засміялася. Учителька додала, що калина означає красу, силу і рідну землю.","Після уроків я спеціально пішов додому повз той паркан. Ягоди висіли низько, майже над самою землею. Я зірвав одну. Тепер я дивлюся на цей кущ зовсім інакше."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 64, 'Нові друзі на мовних курсах', '["Курси польської мови починалися о шостій вечора. На першому занятті кожен писав своє ім''я на папірці. Я написала «Ірина» і поклала його перед собою. Спочатку я трохи хвилювалася, бо не знала в групі нікого. Поруч сиділи люди з різних міст України. Були й студенти з інших країн.","На уроці ми вчили прості слова і короткі діалоги. Викладач говорив повільно. Ліворуч від мене сиділа дівчина з Харкова, а навпроти — хлопець із Грузії. Ми всі однаково плуталися в довгих словах. Після заняття хтось запропонував посидіти разом. Маленьку кав''ярню знайшли просто за рогом.","Там ми пили каву і говорили польською, скільки могли. Коли слів бракувало, переходили на українську. Мої помилки виправляли одразу, і ніхто з цього не сміявся. Тепер я приходжу раніше, щоб устигнути поговорити з ними до уроку."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 65, 'Київ — місто на горах', '["Від вокзалу я пішов пішки і швидко втомився. У Києві вулиця весь час іде або вгору, або вниз, і ноги це відчувають. Місто стоїть на горах над Дніпром. З верхніх вулиць видно річку, мости і дахи нижнього міста. Навіть у центрі всюди дерева, схили і широке небо над водою. Я зупинявся частіше, ніж фотографував.","Другого дня я пішов на Андріївський узвіз. Це вузька вулиця, де сидять художники і продають сувеніри. На столиках лежали картини, вишиті серветки і чашки. Люди йшли повільно, бо хотіли все роздивитися. Я купив магніт для сестри і листівку для мами. Біля сходів грав музикант, а монети дзвеніли в його шапці.","Нагорі я став біля огорожі і подивився вниз. Будинки здавалися маленькими, а Дніпро блищав далеко внизу. Поруч тихо фотографували туристи. Я простояв там довше, ніж збирався."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 66, 'Останній дзвоник', '["Наприкінці травня у школі завжди пахне квітами. Останній дзвоник у нас, як і в усіх школах, був у п''ятницю. Зранку мама застібала мені блузку і казала: «Машо, не крутися». У дворі стояли учні, батьки і вчителі. Біля входу всі фотографувалися.","Найголовніший день був не в нас, а у випускників. Вони стояли попереду з квітами і раптом здавалися набагато старшими, ніж завжди. Кілька дівчат плакали, бо прощалися з класом. Хлопці сміялися і жартували голосніше, ніж треба. Але від класу не відходили.","Учителі бажали всім удачі, легких іспитів і довгого літа. Директор говорив недовго. Потім пролунав дзвоник, і на секунду двір став зовсім тихим. Далі всі плескали, а малюки дивилися знизу вгору.","Я стояла біля своєї подруги і думала про наш клас. Я знаю, що сумуватиму за цими днями. А в понеділок я вже їду до моря."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 67, 'Новий рік: традиції та родина', '["У дитинстві Новий рік починався для мене з запаху мандаринів і хвої. До 2022 року в місті святкували гучно і довго. Люди виходили на площу, купували солодощі і чекали півночі разом. Опівночі феєрверки освітлювали все небо над дахами і над річкою. У дворах діти сміялися, а дорослі вітали сусідів до самого ранку. Удома нас завжди чекав накритий стіл. На ньому були олів''є, запечена картопля, мандарини, сирники і мамин пиріг.","Тепер свято стало тихішим. Після початку повномасштабної війни люди більше думають про безпеку і близьких. Стіл ми накриваємо так само, тільки без гучної музики і без гостей. Уся сім''я збирається разом, як і раніше. Тато перевіряє новини, а мама раз у раз виглядає у вікно. Дідусь згадує минулий рік, а я думаю, чого хочу навчитися далі. Ми телефонуємо родичам, які тепер живуть в інших країнах.","Опівночі ми вітаємо одне одного і бажаємо миру, здоров''я і сил. За вікном іноді видно далекі феєрверки, але їх набагато менше, ніж колись. Ми дивимося коротко і повертаємося до теплого столу. Потім пишемо на папірцях маленькі бажання і кладемо їх біля ялинки. Молодші діти вже сплять на дивані. Хочеться, щоб наступний рік був спокійнішим."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 68, 'Малий бізнес у селі', '["Тетяна живе в невеликому селі, де всі одне одного знають. Її родина тримає пасіку і великий сад. Банок щороку залишалося більше, ніж з''їдала сім''я. Одного дня вона вирішила продавати домашній мед і варення онлайн. Спочатку здавалося, що це просто. Насправді треба було знайти коробки, навчитися фотографувати і писати описи.","Найважче було з покупцями, які не розуміли онлайн-замовлень. Вони дзвонили по кілька разів і питали одне й те саме. Тетяна не сердилася. Вона пояснювала все спокійно, записувала адреси і перевіряла кожну посилку. Іноді син показував їй, як зробити фото телефоном. Перші місяці вона працювала значно більше, ніж заробляла, і майже не спала.","Через пів року в неї з''явилися постійні клієнти. Одні замовляли мед до чаю, а інші варення для дітей. Дехто радив її сторінку друзям. Тепер вона підписує коробки своїм ім''ям."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 69, 'День захисників: листи із фронту', '["У День захисників наш клас не мав звичайних уроків. Учителька принесла чистий папір, конверти і кольорові олівці. Ми писали листи солдатам. Вона сказала, що такі листи важать більше, ніж здається. У класі стало дуже тихо. Я довго не знала, з чого почати. Учителька нахилилася до мене: «Оленко, пиши, як думаєш».","Я намалювала синьо-жовтий прапор у верхньому куті аркуша. Під ним написала: «Дякуємо за захист». Поруч додала сонце і кілька ромашок. Мені хотілося, щоб лист був схожий не на новини, а на лист із дому. Моя подруга написала коротке побажання здоров''я. Хтось намалював дім, садок і кота на паркані.","Після уроку ми поклали листи в конверти. Учителька сказала, що їх передадуть разом з іншою допомогою. Я трохи хвилювалася: мій лист поїде до когось незнайомого. Нехай він знає, що про нього тут пам''ятають."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 70, 'Поїздка до бабусі в село', '["Автобус до Черкаської області їде майже чотири години. Щоліта я проводжу їх біля вікна. За склом тягнуться поля, лісосмуги і маленькі зупинки без назв. Останні кілометри я вже впізнаю кожен поворот. Бабуся стоїть біля хвіртки ще до того, як автобус зупиниться. У селі мене ніхто не називає Олександром — тільки Сашком.","Торгових центрів у селі немає. Зате біля хати росте великий сад, а за городом починається стежка до лісу. Уранці повітря таке чисте, що від нього трохи паморочиться голова. Я ношу бабусі воду, збираю яблука і бігаю на річку. Увечері ми сидимо під старою грушею і слухаємо, як гуде село.","За кілька днів я перестаю поспішати. Сплю до дев''ятої, їм двічі більше, ніж удома. Наприкінці серпня бабуся кладе мені в рюкзак яблука і мед. Я вже рахую, скільки залишилося до наступного літа."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 71, 'Соняшники — символ степу', '["Улітку дорога на південь кілометрами йде між жовтими полями. Соняшники стоять рівними рядами і всі повертають голови в один бік. Такі поля впізнають одразу, навіть на фото з чужої країни. Україна вирощує більше соняшнику, ніж майже будь-яка країна світу. Тому ці квіти видно біля доріг, сіл і залізниць по всій країні. Водії іноді зупиняються, щоб просто постояти на узбіччі. Здалеку таке поле схоже на велике тепле море.","Для багатьох людей соняшник означає дім, тепло і рідну землю. Його малюють на листівках, вишивають на серветках, ставлять у вазу на столі. Восени з насіння роблять олію, і густий запах стоїть на все подвір''я. Дитина, яка виросла в селі, впізнає цей запах із заплющеними очима. Наприкінці літа поле темніє. Але доти воно світиться так, що очам стає гаряче."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 72, 'Українська мова у світі', '["У суботу вранці в Торонто відчиняється невелика школа. Діти приходять туди не по математику, а щоб співати і читати українською. Такі школи вихідного дня є в Канаді, США і Польщі. Українська — одна з найпоширеніших слов''янських мов у світі. Нею говорять в Україні і в українських громадах за кордоном. Удома родини бережуть її просто тим, що розмовляють нею щодня. Діти вчать там привітання, пісні і короткі вірші напам''ять.","Останніми роками українську почали вивчати й ті, хто раніше про неї не думав. Хтось має друзів з України, хтось хоче читати новини без перекладача. На курсах слухають короткі діалоги, повторюють нові слова і плутають наголоси. Найчастіше питають про вимову. Хтось потім їде в Україну і чує ці слова просто на вулиці. Після цього незнайома людина перестає бути зовсім чужою."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 73, 'Перша подорож за кордон', '["У квитку стояло: Марія, шістнадцять років, Київ — Варшава. Це була моя перша поїздка за кордон. Їхали ми з тіткою, і всю дорогу я майже не відривалася від вікна. Раніше інші країни я бачила тільки на фото. Тому я трохи боялася, що все виявиться не таким.","Варшава зустріла широкими вулицями, трамваями і старими будинками в центрі. Польська мова здавалася майже своєю. Я впізнавала окремі слова, а потім губилася в довгих реченнях. Продавчиня в булочній повторила мені все двічі, повільніше. Тітка сміялася, що я розумію кожне третє слово. Це було дивно: близько і водночас не зовсім зрозуміло.","Європа перестала бути для мене картинкою з підручника. Люди там мали свої звички, але багато речей були знайомими. Удома я почала слухати, як говорять іноземці в метро. І вже дивилася, куди можна поїхати наступного літа."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 74, 'День вишиванки: традиція і сучасність', '["Того ранку в нашому класі майже не було звичайного одягу. Сорочки, блузки, навіть светри — усе вишите. День вишиванки припадає на третій четвер травня. Я знала про це, але вперше побачила таке ціле подвір''я. Ми фотографувалися групами і поодинці. Учителька сказала, що сьогодні так само вдягаються українці по всьому світу.","Увечері я знайшла в мережі фото з Торонто і Варшави. Там теж стояли люди у вишитих сорочках, тільки з іншим небом за спиною. Виявилося, що свято придумали студенти. Спочатку їх було кілька десятків в одному університеті. Ніхто не давав наказу, і саме тому воно розійшлося так швидко. Тепер вишиванку вдягають на роботу, на пари і на зустрічі з друзями.","Мене найбільше здивували дизайнери, які поєднують вишивку із сучасним одягом. Узор може бути на жакеті, на сукні або на рукаві футболки. Це вже не музейна річ. Наступного травня я вдягну свою."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 75, 'Гуцульські традиції', '["Дорога в Карпати весь час повертала, і старий автобус їхав зовсім повільно. Гуцули живуть тут, серед лісів, річок і крутих схилів. Минулого літа я потрапив до них уперше. У маленькому музеї нам показали святковий одяг. Кольорів було стільки, що я не одразу побачив крій. Кожна річ мала свій настрій.","Потім майстер показав дерев''яні речі з різьбленням. На них були прості узори, листя і лінії. Він сказав, що така робота потребує часу, гострого ножа і дуже спокійних рук. Ніж рухався так само повільно, як автобус уранці. У дворі вже налаштовували інструменти. Люди готувалися до маленького виступу для гостей.","Найбільше мені запам''ятався танець гуцулка. Скрипка почала швидко, і ноги самі пішли в такт. Танцюристи рухалися легко, а музика піднімала з лавок навіть найстарших. Додому я їхав з адресою того майстра в телефоні."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 76, 'Чорнобиль: пам''ять і уроки', '["У Прип''яті досі стоять будинки, у яких ніхто не живе. На балконах ростуть дерева, а в квартирах залишилися чужі речі. Місто спорожніло за один день. Двадцять шостого квітня 1986 року на Чорнобильській атомній електростанції стався вибух. Люди дізналися про це не одразу. Потім прийшли автобуси, і десятки тисяч людей вивезли з їхніх домівок.","Багатьом сказали, що вони повернуться за три дні. Вони брали документи, трохи одягу і іграшки. Повернутися не вдалося ні через тиждень, ні через рік. Цілі села довелося залишити назавжди. Люди починали життя заново в чужих містах, серед незнайомих сусідів. Найважче було старим, які не хотіли їхати. Дехто ще довго возив із собою ключі від зачинених дверей.","Сьогодні про Чорнобиль говорять спокійно, без зайвих подробиць. Ця історія нагадує, що за землю і за майбутні покоління завжди хтось відповідає. Тому перед великими рішеннями люди тепер питають ще раз. Ключі так і не знадобилися."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 77, 'Ринок «Привоз» в Одесі', '["«Привоз» починається задовго до входу. Уже на тротуарі стоять ящики, відра і перші продавці. Друзі казали, що це один із найвідоміших ринків в Україні. Я прийшов о сьомій ранку, і всередині вже гуло. Далі я йшов повільно, бо не хотів нічого пропустити.","В одному ряду продавали свіжу рибу, ще мокру і блискучу. Поруч лежали фрукти, зелень і сир у великих мисках. А в кінці ряду починалися старі речі: чашки, книжки, годинники і маленькі картини. Продавці не мовчали ні хвилини. Вони жартували, кликали, хвалили свій товар і сміялися одне з одного. Одна жінка сварилася із сусідкою і одночасно зважувала мені яблука.","Ринок був схожий на театр, де вистава йде без перерви. Кожен продавець мав свій голос і свою роль. Мені побажали гарного дня так, ніби ми давно знайомі."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 78, 'Як я готуюся до іспиту', '["Я — Катя, і мій календар на цей тиждень уже розписаний. Іспит через сім днів. У неділю я сіла за стіл і розписала кожен день окремо. У плані є конспекти, картки, тести і обов''язкові перерви на каву. Найважливіше — щовечора викреслювати те, що зробила.","У понеділок і вівторок я перечитую записи з уроків. Те, що не тримається в голові, переписую на маленькі картки. З одного боку слово, з другого — короткий приклад. Картки живуть у кишені і йдуть зі мною навіть у транспорт. Увечері я проходжу онлайн-тести і дивлюся, де помилилася. Помилки виписую окремо і повертаюся до них наступного дня.","Торік я вчила все в останній вечір і майже нічого не пам''ятала вранці. Коли робиш потроху, голова встигає за руками і не втомлюється. Завтра перегляну картки ще раз і ляжу спати раніше."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 79, 'День пам''яті Голодомору: свічка у вікні', '["Молодша сестра першою помітила свічку на столі. Була четверта субота листопада, і темніло вже зовсім рано. Вона спитала, чому свічка стоїть, а ми не святкуємо. Сестра кличе мене Ганнусею, коли їй щось незрозуміло. Пояснювати випало мені, бо я старша на чотири роки. Я сказала їй просто: у 1932-1933 роках Голодомор забрав дуже багато життів.","О сьомій вечора у вікнах по всій країні з''являються вогники. Акція називається «Запали свічку». Мама поставила свічку на підвіконня, а сестрі дала сірник. Та довго не могла його запалити і сердилася на власні пальці. Потім вогник усе-таки з''явився, і вона завмерла. У сусідньому будинку теж світилося одразу три вікна. Далі по вулиці загорілося ще одне, потім ще.","Сестра спитала, що означає ця свічка. Я відповіла: «ми пам''ятаємо». Більше вона нічого не питала. Ми стояли біля вікна, поки віск не потік на блюдце."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 80, 'Традиційний весільний обряд', '["Вінок для нареченої плетуть заздалегідь, іноді за кілька днів. У нього вплітають живі квіти і кольорові стрічки. Це одна з найстаріших весільних традицій в Україні. У різних родинах усе трохи інакше, але головне збігається. Гості приходять у гарному одязі, з квітами і подарунками. Двір наповнюється голосами задовго до початку.","На одному з обрядів молодята тричі обходять стіл. Старші родичі стежать, щоб коло не розірвалося. Так починається спільне життя. Потім співають, і хтось обов''язково заспівує перший. За піснями йдуть танці, і потім уже ніхто не хоче сідати за стіл. Молодята встигають не все, але їм ніхто не дорікає.","Нарешті всі сідають за великий стіл. На ньому борщ, вареники, м''ясо, салати і солодке. Діти дивляться на танці, а бабусі згадують власні весілля. Котрась із них скоро покаже онуці, як плести вінок."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 81, 'День Героїв Небесної Сотні: пам''ять і вибір', '["На вчительському столі стояла свічка і кілька білих паперових квітів. Ми зайшли в клас і стишили голоси. Двадцятого лютого Україна вшановує Героїв Небесної Сотні. Це люди Революції Гідності, які загинули на Майдані у 2014 році. Учителька говорила простими словами і жодного разу не підвищила голосу. Хтось запитав, скільки їм було років, і ніхто не відповів одразу.","Вона сказала, що ці люди хотіли вільної і справедливої країни. Потім ми довго говорили про саме слово «свобода», і клас не поспішав. Я думав, що воно означає робити те, що хочеш. Виявилося, що це тільки половина. Друга половина — відповідати за те, що ти зробив. Про це на уроках раніше не говорили.","Після дзвінка ніхто не побіг у коридор. Я сидів біля вікна і довго дивився, як за склом іде мокрий сніг. Свічка на столі догоріла майже до кінця. Додому я йшов повільніше, ніж завжди."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 82, 'Сільська гостинність', '["Автобус висадив нас біля воріт, і господарі вже стояли там і махали руками. Нас було восьмеро, і в українське село я приїхала вперше. У хаті на столі парував борщ і лежав домашній хліб. Поруч стояли сметана і зелень, зрізана хвилину тому. Питати нас ніхто не став.","Після обіду господар повів нас у сад. Там росли яблуні, сливи, помідори і огірки. Він давав куштувати геть усе, повз що ми проходили. Потім господиня відчинила льох, і зверху війнуло холодом. На полицях стояли банки з варенням, огірками і компотом. Вона рахувала їх уголос і збилася на третьому ряду.","Ми об''їздили багато країн, але такої гостинності ще ніде не бачили. Увечері нам винесли чай просто у двір. Ніхто нікуди не поспішав, і розмова сама собою стихла. Я досі пам''ятаю, як пахнув той льох."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 83, 'Екологія і Карпати', '["Деякі буки в карпатських лісах старші за будь-яку хату в найближчому селі. Їм по кілька сотень років. Такі ліси більше ніде в Європі не збереглися так добре. Між стовбурами майже завжди сутінки, навіть опівдні. Повітря там вологе і пахне мокрою корою. Туристи в таких місцях самі починають говорити тихіше.","Небезпека приходить не з погодою, а з дорогою. Там, де ліс вирубують без контролю, схили залишаються голими. Після дощу вода біжить униз дуже швидко і несе із собою верхню землю. Струмки міліють, а звірам стає нікуди подітися. Молоді дерева на місці старих ростуть десятиліттями. Один зрізаний схил видно з дороги за кілометр.","Про це першими заговорили місцеві школярі і студенти. Вони прибирають стежки, проводять зустрічі і збирають підписи. Листи до громади вони пишуть від руки, по одному на кожен клас. Підписів під ними щороку більше."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 84, 'Мій улюблений український письменник', '["Портрет Шевченка висить у нашому класі над дошкою. Я дивилася на нього чотири роки і майже ніколи не помічала. Минулого тижня я готувала про нього розповідь. Учителька сказала, що це найвідоміший поет України. Виявилося, що я не знала про нього майже нічого.","Удома бабуся дістала з шафи стару книжку «Кобзар». Обкладинка була потерта, а всередині лежала засушена синя квітка. Таку книжку тримали в багатьох українських домівках. Шевченко писав про свободу, рідну землю і звичайних людей. Не про королів і не про битви, а про тих, хто поруч. Бабуся прочитала мені один вірш уголос і зупинилася на середині.","Деякі слова я не зрозуміла, і вона пояснила їх своїми. Читати виявилося легше вголос. «Кобзар» тепер лежить у мене на столі, поруч із підручниками. Я дійшла до сорок другої сторінки."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 85, 'День Соборності: одна країна, різні голоси', '["Учитель повісив на дошці стару карту з іншими кордонами. На ній Україна була поділена на дві частини. Двадцять другого січня в країні відзначають День Соборності. У 1919 році ці частини вирішили стати однією державою. Легко тоді не було нікому. На заході і на сході люди жили по-різному вже кілька поколінь поспіль.","Різні традиції, різні звички, а часом навіть різні слова для тих самих речей. Хтось жив біля моря, хтось у горах, хтось у степу. Учитель спитав нас, що могло їх тоді об''єднати. Ми довго не могли відповісти. Виявилося, що спільна мрія про незалежність важила більше за всі відмінності. Домовитися вони змогли не одразу, але змогли.","Після уроку я думав про це всю дорогу додому. Єдність — це не коли всі однакові. Країна з різними голосами багатша за країну з одним. Удома дід сказав, що його село тоді було по той бік лінії."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 86, 'Холодець на Різдво', '["Холодець у нас варять двічі на рік — на Різдво і на Новий рік. Починається все звечора, коли на плиту ставлять велику каструлю. У ній кілька годин вариться свинина або курка. Кухня тоді пахне так, що з неї не хочеться виходити. Мама каже, що раніше ніж за чотири години пробувати немає сенсу.","Пізно ввечері дорослі розливають гарячий холодець у широкі миски. Далі його виносять на балкон і залишають до ранку. Уночі туди краще не заглядати. Зранку страва вже тримає форму і блищить, як скло. Бабуся кладе зверху кілька кружечків моркви. Робить вона це щоразу однаково. Ніхто не питає її чому.","За столом тато бере холодець із хроном, а дідусь — з гірчицею. Мені більше смакує просто з хлібом. Сестра їсть саму моркву. Миска порожніє швидше за все інше на столі."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 87, 'Дванадцять страв на Святий вечір', '["Рахувати тарілки в нашому домі щороку доручають мені. Їх має бути дванадцять, і жодної менше. Сьомого січня наша родина святкує Різдво за юліанським календарем. Так роблять багато православних українців. Увечері перед святом ми накриваємо стіл на Святий вечір. Бабуся ще зранку перевіряє, чи всім вистачить узвару.","Першою на стіл ставлять кутю, і чіпати її поки не можна. Далі йдуть узвар, вареники з капустою, голубці і смажена риба. Бабуся додає гриби, квасолю і два простих салати. Усі назви я не запам''ятовую, але бачу, що кожна страва має своє місце. Дванадцятою виявляється тарілка, про яку всі забули. Її приносять останньою, і рахунок нарешті сходиться.","У хаті пахне узваром і теплим хлібом. Ми говоримо тихо і чекаємо тих, хто ще в дорозі. Коли заходить останній, стільців уже не вистачає. Хтось приносить табуретку, і всі сідають."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 88, 'Чому я вивчаю іноземні мови', '["Мій зошит поділений навпіл: ліва половина англійська, права польська. Мене звати Оксана, і я веду його вже другий рік. Англійська — для фільмів, пісень і подорожей. Польську вчу через двоюрідних сестер, які давно живуть у Польщі. Займаюся тричі на тиждень і виписую нові слова стовпчиком.","На курсах я вже знайшла двох подруг. Одна вчить англійську з нуля, а друга приїхала з Луцька. Ми пишемо одне одному короткі повідомлення різними мовами. Помилки виправляємо відразу і майже без сорому. Минулого місяця я вперше зрозуміла цілу пісню без жодного перекладу і без словника. Слухала її потім разів десять.","Я хочу працювати перекладачкою або журналісткою. Для цього двох мов замало, і я про це вже знаю. Іноді навчання набридає, особливо довга граматика. Але зошит уже майже закінчився, і я купила другий."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 89, 'Допомога ветеранам', '["Суботній ранок у громадському центрі починається рівно о дев''ятій. Волонтери приходять першими і беруть список справ. Він щотижня інший і завжди довший, ніж здається. Потім приходять ветерани — по документи, по продукти, на розмову. Хтось приносить папку з документами, хтось порожню сумку. Ніхто нікого не квапить.","Одні волонтери сідають заповнювати заяви і шукати потрібні довідки. Інші йдуть до магазину і несуть назад важкі пакети. Двоє щосуботи супроводжують чоловіка на реабілітацію і чекають його в коридорі. Розмови починаються самі, десь на третьому поверсі або в черзі до ліфта. Після справ усі п''ють чай із одного чайника. Тоді й розповідають найбільше.","Керівниця центру каже, що самої пам''яті замало, якщо нема кому донести сумку. Волонтери втомлюються, але до вечора список завжди порожній. Наступної суботи приходять ті самі люди і ще двоє нових."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 90, 'Кава по-львівськи', '["Двері кав''ярні виявилися такими низькими, що я мимоволі нахилилася. Усередині пахло смаженою кавою і чимось солодким. Львів часто називають кавовою столицею України. Тут кав''ярня стоїть майже в кожному дворі старого міста. На стінах висіли старі фото і чорна дерев''яна вивіска. Біля вікна сиділи студенти з книжками і однією чашкою на двох.","Офіціант приніс меню і порадив каву по-львівськи. Він сказав, що в кожній кав''ярні тут свій рецепт і свій характер. Я взяла те, що порадили. Каву подали в маленькій чашці, а поруч поставили шоколад і склянку холодної води. Вода поруч була зовсім крижана.","Я пила повільно і дивилася у вікно. Люди йшли по бруківці, і десь поруч тихо грав акордеон. Шоколад робив каву м''якшою, а вода повертала смак назад. Свою чашку я допивала останньою в залі."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 91, 'Трійця і клечання', '["Зелень на базар привозять просто снопами. Ми з мамою купуємо аж дві оберемки і ледве несемо їх додому. Трійця приходить на п''ятдесятий день після Великодня. Мама рахує ці дні на календарі щовесни. Удома ми спершу відсуваємо килим і миємо підлогу. Тільки після цього можна братися за гілки.","Потім починається найцікавіше. Зелені гілки ставимо біля дверей, а свіжі трави кладемо на підвіконня. Бабуся каже, що цей звичай називається клечання. Слово я запам''ятав з першого разу. Тато приносить ще кілька гілочок для коридору. Я ставлю маленький букет просто на кухонний стіл. До вечора зелень є в кожній кімнаті.","У квартирі пахне м''ятою і мокрим листям. Так пахне двір після дощу, коли все починається спочатку. Мама вимикає світло, а зелень усе одно видно біля дверей. Уранці я прокинувся раніше за будильник — від запаху."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 92, 'Переваги роботи онлайн', '["Сестрин ноутбук стоїть на кухонному столі щодня з восьмої ранку. Іноді вона бере його і йде в тиху кав''ярню за рогом. Так тепер працює багато українців. Хтось із її колег живе у Львові, а хтось торік переїхав до Варшави. Бачаться вони тільки на екрані.","Спочатку я думала, що це найлегша робота на світі. Хочеш — працюй у піжамі, хочеш — узагалі не вставай. Сестра каже, що саме тут усе найчастіше й ламається. Щоранку вона пише розклад і ставить у нього час для перерв. Телефон на цей час лежить екраном донизу. Без розкладу день зникає, а справи залишаються на місці.","Одного разу я сиділа поруч у кав''ярні цілу годину. Кава біля неї так і застигла холодною. Увечері вона закриває ноутбук рівно о шостій і йде гуляти. Кухонний стіл до ранку знову стає кухонним."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 93, 'Водохреща', '["Мороз того ранку був такий, що сніг рипів під ногами. Ми з татом вийшли з дому ще затемна, о сьомій. Дев''ятнадцятого січня в Україні святкують Водохреща. До річки йшли не тільки ми. Біля води вже стояли люди і чомусь говорили пошепки. Ніхто нікуди не поспішав.","У кризі був вирубаний рівний отвір і поставлені дерев''яні сходи. Кілька людей зайшли у воду просто в такий мороз. Заходили обережно, трималися за поручень і виходили дуже швидко. На березі їх одразу загортали в рушники. Кажуть, що ця вода очищає і тіло, і душу на цілий рік. Хтось на березі рахував уголос секунди.","Додому ми поверталися вже видною дорогою. Мама налила нам гарячого чаю з лимоном. Я грів об чашку руки і довго не міг їх відчути. Тато сидів навпроти і теж мовчав."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 94, 'День Гідності та Свободи: що він означає сьогодні', '["Тато завжди відповідає одразу, на будь-яке питання. Того вечора він не відповів. Двадцять першого листопада ми мали урок про День Гідності та Свободи. Учителька сказала, що революції почалися у 2004 і 2013 роках. Для нас це сторінки в підручнику. Для дорослих у класі це був би зовсім інший урок. Я слухав і весь урок думав про свого тата.","Після уроку я прийшов додому і запитав тата, чи був він на Майдані. Тато не відповів одразу. Він поставив чашку на стіл і подивився у вікно. Потім назвав мене повним ім''ям — Олексієм. Сказав, що пам''ятає той час дуже добре, до дня. Але говорити про нього легко не завжди.","Голос у нього став тихішим, ніж звичайно. Тато сказав, що люди тоді хотіли поваги, свободи і чеснішої країни. Більше я нічого не питав. Ми досиділи до кінця чайника мовчки."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 95, 'Народна медицина в Україні', '["Коли я застуджуюся, бабуся приходить на кухню зі своїми баночками. У неї їх ціла полиця, і на кожній наклейка з роком і назвою. Усередині сухий чебрець, материнка і м''ята. Мед стоїть окремо, у великій банці з дерев''яною ложкою. Малинове варення дістають із шафи тільки в такі дні.","Спершу мама телефонує лікарці й докладно розповідає про температуру. Тільки після цього на плиту ставлять чайник. Бабуся заварює чебрець, кидає туди ложку меду і накриває чашку блюдцем. Каже, що так довше тримається тепло. Ліки лежать поруч із чашкою, на тій самій серветці. Одне іншому не заважає.","Чай я п''ю дуже повільно, бо він гарячий і пахне травами. Потім лягаю під ковдру і беру книжку. Бабуся тихо зачиняє двері й забирає із собою навіть кота. Так день минає повільніше, ніж усі інші."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 96, 'День Конституції: права і обов''язки', '["У кожній бібліотеці країни є тонка книжка в синій обкладинці. Це Конституція України, головний закон держави. Її ухвалили двадцять восьмого червня 1996 року. Відтоді цей день є державним святом. Книжка невелика, але саме вона визначає правила для всіх. Прочитати її може будь-хто, і мова там простіша, ніж здається.","У Конституції записано, що людина має право говорити вільно. Має право вчитися і лікуватися. Має право не боятися за себе і свою родину. Ці права не залежать від того, багата людина чи ні. Але записане право і право, яке справді працює, — не одне й те саме. Демократія працює тоді, коли люди знають і права, і обов''язки.","Тому Конституцію читають не тільки юристи. Хтось перевіряє, чи має право на безкоштовну операцію. Хтось питає, чому в дворі зрубали дерева. Обов''язки в тій самій книжці й на тих самих сторінках."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 97, 'Фестиваль «Країна Мрій»', '["Учителька музики принесла на урок стару афішу. На ній великими літерами стояло: «Країна Мрій». Це відомий фестиваль етнічної музики. Раніше він щоліта проходив у Києві, просто неба. Туди приїжджали гурти з різних країн і з усіх куточків України. Афіша була пом''ята, з дірками від кнопок по кутах.","Потім ми дивилися коротке відео з того фестивалю. На сцені стояли люди у вишиванках, а перед сценою танцювали всі підряд. Музика починалася повільно, майже як колискова. Через хвилину під неї вже можна було стрибати. Барабан звучав сучасно, а голос — зовсім давно. Молоді люди в залі знали приспіви напам''ять і співали разом. Ніхто з них не виглядав так, ніби прийшов у музей.","Після уроку я знайшов кілька записів удома. Слухав їх до вечора, поки не сів телефон. Одну пісню поставив на будильник. Тепер прокидаюся під барабан."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 98, 'Листи до рідних', '["Дорогі мамо і тату!","Пишу вам справжнього паперового листа, бо хочу, щоб ви тримали його в руках. Я вже два місяці живу за кордоном. Тут усе нове: вулиці, магазини, мова і навіть ранкова кава. Найдивніше тут те, що хліб продають уже нарізаним. Але я часто думаю про наш дім і вашу кухню.","Сьогодні я купила конверт і красиву марку в маленькій крамниці. Продавчиня довго вибирала мені марку з квітами. Знаю, що мама читає кожен мій лист кілька разів. Тато казав, що ви складаєте всі листи в коробку біля шафи. Порахуйте, будь ласка, скільки їх там уже. Коробка, мабуть, уже не закривається.","Я сумую за вами, але вчуся бути сміливою. Передайте привіт бабусі і нашому коту. Я скоро напишу знову і покладу в конверт нову марку. Обіймаю вас міцно. Ваша Олена."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 99, 'Українці у світі', '["Українську я почув у автобусі, за три зупинки від дому. Двоє чоловіків голосно говорили про футбол, і я мимоволі усміхнувся. Тут, за кордоном, таке трапляється частіше, ніж я думав. Українці живуть від Канади до Австралії. У великих містах і в містечках, про які ніхто не чув.","Мову тут бережуть найпростішим способом — розмовляють нею вдома. У неділю діти йдуть до школи вдруге за тиждень. Там вони вчать пісні, букви і короткі вірші. Раз на рік громада влаштовує фестиваль у міському парку. Варять борщ у великих каструлях і танцюють просто на траві до темряви. Вишиванки дістають навіть ті, хто носить їх раз на рік.","Коли в Україні стало важко, тут почали збирати гроші і ліки. Ніхто не домовлявся заздалегідь. Просто в один тиждень усі почали робити те саме. Тепер в автобусі я озираюся першим."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 100, 'Одеса: місто між морем і степом', '["Одеса починається запахом ще до вокзалу. Море чути раніше, ніж видно. За містом одразу починається степ — рівний, жовтий і безкінечний. Між ними стоїть місто, у якому все це давно перемішалося між собою. Я приїжджаю сюди щоліта і гублюся в однакових дворах. Тут ніхто не показує дорогу мовчки.","Потьомкінські сходи згори здаються коротшими, ніж знизу. Я рахувала їх і двічі збилася. Хтось знизу гукнув мені правильну цифру. Увечері біля оперного театру збираються люди в гарному одязі. Квитків не було, тому ми слухали музику знадвору разом з іншими такими ж. Поруч продавали морозиво і голосно сперечалися про його ціну. Сперечалися весело, ніби це частина вистави.","Уранці я зайшла на «Привоз» по абрикоси для дороги. Продавчиня зважила кілограм і додала ще жменю зверху. Сказала, що я схожа на її молодшу доньку. Абрикоси я з''їла ще дорогою до моря."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 101, 'Волонтерство як стиль життя', '["Волонтерський центр працює в колишньому меблевому магазині. Вивіску не знімали, тому там досі написано «Дивани». Після 2022 року такі центри відкрилися майже в кожному районі. Я приходжу сюди тричі на тиждень, після пар. Тут студенти, пенсіонери, вчителі і жінка з нашого під''їзду. Її я бачив тільки біля ліфта.","Одні плетуть маскувальні сітки, і руки в них зелені аж до ліктів. Інші збирають гроші на обладнання і рахують їх двічі. Хтось сортує одяг, ліки і продукти для гуманітарної допомоги. Я пакую коробки і пишу списки, щоб нічого не загубилося. Робота проста, але помилятися в ній не можна. Мій почерк тут уперше в житті став розбірливим.","Найбільше говорять не про роботу, а про звичайні речі. Хто де вчився, у кого нарешті зацвів кактус і чий кіт знову втік. Тому сюди й ходять — щоб не сидіти вдома самому. Коробок сьогодні вийшло сорок дві."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 102, 'Що означає бути українцем', '["У шафі в бабусі висить вишиванка в білому чохлі. Дістають її двічі на рік і завжди чомусь мовчки. Бабуся каже, що її шила ще її мати. Мене назвали Яриною на честь тієї жінки. Паспорт у мене такий самий, як у всіх. А вишиванка одна. Я міряла її один раз, у сім років.","Бути українкою — це не місце народження. Це мова, яку я чую вдома щодня. Це пісні, які мама співала мені до сну. Це борщ, який у нас варять у неділю. Це червона калина біля воріт, гірка і дуже помітна. Кожна з цих речей зовсім маленька, а разом вони тримають.","Торік у нас двічі не було світла по чотири дні поспіль, узимку. Бабуся тоді дістала свічки і поставила на газ старий чайник. Сказала, що серце ламається не від темряви. Я запам''ятала."]', 1, 1);
INSERT INTO texts (level, display_order, title, paragraphs_json, show_word_count, is_enabled) VALUES ('A2', 103, 'Україна і світ: новий погляд', '["На уроці географії мене попросили показати Київ на карті. Половина класу думала, що це десь біля Москви. Я показав і сказав, що до моря звідти всього сім годин потягом. Про Україну тут почули через війну. Але питають мене не тільки про неї. Питають про музику, про художників і про те, що ми їмо на свята.","Нас таких у школі четверо. Ми, українці за кордоном, стали чимось на зразок маленьких послів. На Великдень я приніс пасок, і його з''їли за одну перерву. Мене питали, чому вона солодка і чому зверху біла глазур. Найважче було пояснити слово «незламність». Я сказав, що це коли ламається все навколо, а людина ні. Потім це слово вживали навіть учителі.","Друзі повторювали слово повільно, по складах. Одна дівчина записала його собі в телефон. Коли пояснюєш свою країну іншим, починаєш розуміти її сам. Тепер я не мовчу, коли при мені кажуть дурниці."]', 1, 1);
